use std::io::Write;

/// Output buffer that accumulates escape sequences and text.
pub struct Out {
    pub buf: Vec<u8>,
}

impl Out {
    pub fn new() -> Self {
        Out { buf: Vec::with_capacity(16384) }
    }
    pub fn s(&mut self, s: &str) {
        self.buf.extend_from_slice(s.as_bytes());
    }
    /// Move to (col,row), both 1-based.
    pub fn mv(&mut self, col: usize, row: usize) {
        let _ = write!(self.buf, "\x1b[{};{}H", row, col);
    }
    pub fn clear_all(&mut self) {
        self.s("\x1b[2J");
    }
    pub fn clear_line(&mut self) {
        self.s("\x1b[2K");
    }
    pub fn clear_eol(&mut self) {
        self.s("\x1b[K");
    }
    pub fn hide(&mut self) {
        self.s("\x1b[?25l");
    }
    pub fn show(&mut self) {
        self.s("\x1b[?25h");
    }
    pub fn reset(&mut self) {
        self.s("\x1b[0m");
    }
    pub fn reverse(&mut self) {
        self.s("\x1b[7m");
    }
    pub fn bold(&mut self) {
        self.s("\x1b[1m");
    }
    pub fn left(&mut self, n: usize) {
        let _ = write!(self.buf, "\x1b[{}D", n);
    }
    pub fn right(&mut self, n: usize) {
        let _ = write!(self.buf, "\x1b[{}C", n);
    }
    pub fn fg(&mut self, c: &Color) {
        match c {
            Color::Ansi(n) => {
                let _ = write!(self.buf, "\x1b[38;5;{}m", n);
            }
            Color::Rgb(r, g, b) => {
                let _ = write!(self.buf, "\x1b[38;2;{};{};{}m", r, g, b);
            }
        }
    }
    pub fn bg(&mut self, c: &Color) {
        match c {
            Color::Ansi(n) => {
                let _ = write!(self.buf, "\x1b[48;5;{}m", n);
            }
            Color::Rgb(r, g, b) => {
                let _ = write!(self.buf, "\x1b[48;2;{};{};{}m", r, g, b);
            }
        }
    }
    pub fn flush(&mut self) {
        if self.buf.is_empty() {
            return;
        }
        let mut so = std::io::stdout();
        let _ = so.write_all(&self.buf);
        let _ = so.flush();
        self.buf.clear();
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Color {
    Ansi(u8),
    Rgb(u8, u8, u8),
}

pub fn terminal_size() -> (usize, usize) {
    match crossterm::terminal::size() {
        Ok((w, h)) => (w as usize, h as usize),
        Err(_) => (80, 24),
    }
}
EOF
echo ok"}

