use std::cmp::Ordering;

fn fold(c: char, ignore_case: bool) -> char {
    if ignore_case {
        c.to_lowercase().next().unwrap_or(c)
    } else {
        c
    }
}

fn is_digit(c: Option<&char>) -> bool {
    matches!(c, Some(ch) if ch.is_ascii_digit())
}

fn compare_right(a: &[char], b: &[char]) -> Ordering {
    let mut bias = Ordering::Equal;
    let mut i = 0;
    loop {
        let ca = a.get(i);
        let cb = b.get(i);
        let da = is_digit(ca);
        let db = is_digit(cb);
        if !da && !db {
            return bias;
        }
        if !da {
            return Ordering::Less;
        }
        if !db {
            return Ordering::Greater;
        }
        let (x, y) = (ca.unwrap(), cb.unwrap());
        if x < y {
            if bias == Ordering::Equal {
                bias = Ordering::Less;
            }
        } else if x > y && bias == Ordering::Equal {
            bias = Ordering::Greater;
        }
        i += 1;
    }
}

fn compare_left(a: &[char], b: &[char]) -> Ordering {
    let mut i = 0;
    loop {
        let ca = a.get(i);
        let cb = b.get(i);
        let da = is_digit(ca);
        let db = is_digit(cb);
        if !da && !db {
            return Ordering::Equal;
        }
        if !da {
            return Ordering::Less;
        }
        if !db {
            return Ordering::Greater;
        }
        let (x, y) = (ca.unwrap(), cb.unwrap());
        if x < y {
            return Ordering::Less;
        }
        if x > y {
            return Ordering::Greater;
        }
        i += 1;
    }
}

pub fn natcmp(a: &str, b: &str, ignore_case: bool) -> Ordering {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut ai = 0;
    let mut bi = 0;
    loop {
        while ai < a.len() && a[ai].is_whitespace() {
            ai += 1;
        }
        while bi < b.len() && b[bi].is_whitespace() {
            bi += 1;
        }
        let ca = a.get(ai);
        let cb = b.get(bi);
        if is_digit(ca) && is_digit(cb) {
            let frac = *ca.unwrap() == '0' || *cb.unwrap() == '0';
            let r = if frac {
                compare_left(&a[ai..], &b[bi..])
            } else {
                compare_right(&a[ai..], &b[bi..])
            };
            if r != Ordering::Equal {
                return r;
            }
        }
        match (ca, cb) {
            (None, None) => return Ordering::Equal,
            (None, Some(_)) => return Ordering::Less,
            (Some(_), None) => return Ordering::Greater,
            (Some(&x), Some(&y)) => {
                let x = fold(x, ignore_case);
                let y = fold(y, ignore_case);
                if x < y {
                    return Ordering::Less;
                }
                if x > y {
                    return Ordering::Greater;
                }
            }
        }
        ai += 1;
        bi += 1;
    }
}
EOF
