use crate::term::Color;
use serde::Deserialize;
use std::path::PathBuf;

#[derive(Deserialize, Debug, Clone)]
pub enum Colorname {
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    LightBlack,
    LightRed,
    LightGreen,
    LightYellow,
    LightBlue,
    LightMagenta,
    LightCyan,
    LightWhite,
    Rgb(u8, u8, u8),
    AnsiValue(u8),
}

impl Colorname {
    pub fn to_color(&self) -> Color {
        match self {
            Colorname::Black => Color::Ansi(0),
            Colorname::Red => Color::Ansi(1),
            Colorname::Green => Color::Ansi(2),
            Colorname::Yellow => Color::Ansi(3),
            Colorname::Blue => Color::Ansi(4),
            Colorname::Magenta => Color::Ansi(5),
            Colorname::Cyan => Color::Ansi(6),
            Colorname::White => Color::Ansi(7),
            Colorname::LightBlack => Color::Ansi(8),
            Colorname::LightRed => Color::Ansi(9),
            Colorname::LightGreen => Color::Ansi(10),
            Colorname::LightYellow => Color::Ansi(11),
            Colorname::LightBlue => Color::Ansi(12),
            Colorname::LightMagenta => Color::Ansi(13),
            Colorname::LightCyan => Color::Ansi(14),
            Colorname::LightWhite => Color::Ansi(15),
            Colorname::Rgb(r, g, b) => Color::Rgb(*r, *g, *b),
            Colorname::AnsiValue(n) => Color::Ansi(*n),
        }
    }
}

#[derive(Deserialize, Debug, Clone)]
pub struct ConfigColor {
    pub dir_fg: Colorname,
    pub file_fg: Colorname,
    pub symlink_fg: Colorname,
    pub dirty_fg: Colorname,
}

#[derive(Deserialize, Debug, Clone, Default)]
pub struct ConfigFile {
    pub default: Option<String>,
    pub exec: Option<serde_yaml::Mapping>,
    pub match_vim_exit_behavior: Option<bool>,
    pub ignore_case: Option<bool>,
    pub color: Option<ConfigColor>,
}

#[derive(Debug, Clone)]
pub struct Colors {
    pub dir: Color,
    pub file: Color,
    pub symlink: Color,
    pub dirty: Color,
}

#[derive(Debug, Clone)]
pub struct Config {
    pub default: Option<String>,
    /// (command, extensions) in file order
    pub exec: Vec<(String, Vec<String>)>,
    pub match_vim_exit_behavior: bool,
    pub ignore_case: bool,
    pub colors: Colors,
    pub path: Option<PathBuf>,
}

impl Config {
    pub fn default_colors() -> Colors {
        Colors {
            dir: Color::Ansi(14),
            file: Color::Ansi(15),
            symlink: Color::Ansi(11),
            dirty: Color::Ansi(1),
        }
