use crate::natsort::natcmp;
use crate::session::SortKey;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use unicode_width::UnicodeWidthChar;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum FileType {
    Directory,
    File,
    Symlink,
}

#[derive(Clone, Debug)]
pub struct Item {
    pub name: String,
    pub path: PathBuf,
    pub ftype: FileType,
    pub is_dir_like: bool,
    pub target: Option<PathBuf>,
    pub size: u64,
    pub ext: Option<String>,
    pub mtime: Option<String>,
    pub mtime_secs: i64,
    pub perm: Option<u32>,
    pub dirty: bool,
    pub selected: bool,
    pub matches: bool,
}

pub fn char_width(c: char) -> usize {
    c.width().unwrap_or(0)
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

/// Truncate to fit `max` columns (no ellipsis).
pub fn truncate_width(s: &str, max: usize) -> String {
    let mut w = 0;
    let mut out = String::new();
    for c in s.chars() {
        let cw = char_width(c);
        if w + cw > max {
            break;
        }
        w += cw;
        out.push(c);
    }
    out
}

/// Shorten item name for the list.
pub fn shorten_name(name: &str, area: usize) -> String {
    if name.len() <= area {
        return name.to_string();
    }
    let limit = area.saturating_sub(2);
    let mut s = truncate_width(name, limit);
    s.push_str("..");
    s
}

pub fn format_time(t: std::time::SystemTime) -> String {
    let dt: chrono::DateTime<chrono::Local> = t.into();
    dt.format("%Y-%m-%d %H:%M").to_string()
}

pub fn format_size(size: u64) -> String {
    if size < 1000 {
        format!("{}B", size)
    } else if size < 1_000_000 {
        format!("{}KB", size / 1000)
    } else if size < 1_000_000_000 {
        format!("{}MB", size / 1_000_000)
    } else {
        format!("{}GB", size / 1_000_000_000)
    }
}

pub fn get_ext(path: &Path) -> Option<String> {
    path.extension()
        .map(|e| e.to_string_lossy().to_lowercase())
}

pub fn make_item(path: &Path, name: String, dirty_paths: &[PathBuf]) -> Option<Item> {
    let meta = std::fs::symlink_metadata(path).ok()?;
    let ft = meta.file_type();
    let ftype = if ft.is_symlink() {
        FileType::Symlink
    } else if ft.is_dir() {
        FileType::Directory
    } else {
        FileType::File
    };
    let (target, is_dir_like) = match ftype {
        FileType::Symlink => (std::fs::canonicalize(path).ok(), path.is_dir()),
        FileType::Directory => (None, true),
        FileType::File => (None, false),
    };
    let mtime_sys = meta.modified().ok();
    let mtime = mtime_sys.map(format_time);
    let mtime_secs = meta.mtime();
    let ext = if ftype == FileType::Directory {
        None
    } else {
        get_ext(path)
    };
    let dirty = dirty_paths.iter().any(|d| d.starts_with(path));
    Some(Item {
        name,
        path: path.to_path_buf(),
        ftype,
        is_dir_like,
        target,
        size: meta.len(),
        ext,
        mtime,
        mtime_secs,
        perm: Some(meta.mode() & 0o777),
        dirty,
        selected: false,
        matches: false,
    })
}

pub fn list_dir(
    dir: &Path,
    show_hidden: bool,
    sort: SortKey,
    dirty_paths: &[PathBuf],
) -> std::io::Result<Vec<Item>> {
    let rd = std::fs::read_dir(dir)?;
    let mut dirs = vec![];
    let mut files = vec![];
    for e in rd.flatten() {
        let name = e.file_name().to_string_lossy().into_owned();
        if !show_hidden && name.starts_with('.') {
            continue;
        }
        let path = e.path();
        if let Some(it) = make_item(&path, name, dirty_paths) {
            if it.is_dir_like {
                dirs.push(it);
            } else {
                files.push(it);
            }
        }
    }
    sort_items(&mut dirs, sort);
    sort_items(&mut files, sort);
    dirs.extend(files);
    Ok(dirs)
}

pub fn sort_items(v: &mut [Item], sort: SortKey) {
    match sort {
        SortKey::Name => v.sort_by(|a, b| natcmp(&a.name, &b.name, true)),
        SortKey::Time => v.sort_by(|a, b| b.mtime_secs.cmp(&a.mtime_secs)),
    }
}

/// Re-sort an existing list (dirs first).
pub fn resort(items: &mut Vec<Item>, sort: SortKey) {
    let mut dirs: Vec<Item> = vec![];
    let mut files: Vec<Item> = vec![];
    for it in items.drain(..) {
        if it.is_dir_like {
            dirs.push(it);
        } else {
            files.push(it);
        }
    }
    sort_items(&mut dirs, sort);
    sort_items(&mut files, sort);
    dirs.extend(files);
    *items = dirs;
}

impl Item {
    pub fn footer(&self, index: usize, len: usize) -> String {
        match self.ftype {
            FileType::Symlink => match &self.target {
                Some(t) => format!(" linked to: {}", t.display()),
                None => " linked to: (invalid path)".to_string(),
            },
            _ => {
                let mut s = format!(" {}/{} ", index + 1, len);
                if self.ftype == FileType::File {
                    if let Some(e) = &self.ext {
                        s.push_str(e);
                        s.push(' ');
                    }
                }
                s.push_str(&format_size(self.size));
                s.push(' ');
                if let Some(p) = self.perm {
                    s.push_str(&format!("{:03o}", p));
                }
                s
            }
        }
    }
}
EOF
echo ok"}

