/// Re-sort an existing list (dirs first).
pub fn resort(items: &mut Vec<Item>, sort: SortKey) {
    let mut dirs: Vec<Item> = vec![];
    let mut files: Vec<Item> = vec![];
    for it in items.drain(..) {
        if it.is_dir_like {
            dirs.push(it);
        } else {
            files.push(it);
        }
    }
    sort_items(&mut dirs, sort);
    sort_items(&mut files, sort);
    dirs.extend(files);
    *items = dirs;
}

impl Item {
    pub fn footer(&self, index: usize, len: usize) -> String {
        match self.ftype {
            FileType::Symlink => match &self.target {
                Some(t) => format!(" linked to: {}", t.display()),
                None => " linked to: (invalid path)".to_string(),
            },
            _ => {
                let mut s = format!(" {}/{} ", index + 1, len);
                if self.ftype == FileType::File {
                    if let Some(e) = &self.ext {
                        s.push_str(e);
                        s.push(' ');
                    }
                }
                s.push_str(&format_size(self.size));
                s.push(' ');
                if let Some(p) = self.perm {
                    s.push_str(&format!("{:03o}", p));
                }
                s
            }
        }
    }
}
