fn is_image(head: &[u8]) -> bool {
    if head.len() < 12 {
        return false;
    }
    let sigs: &[&[u8]] = &[
        b"\x89PNG\r\n\x1a\n",
        b"\xff\xd8\xff\xdb",
        b"\xff\xd8\xff\xe0",
        b"\xff\xd8\xff\xee",
        b"GIF87a",
        b"GIF89a",
        b"II*\x00",
        b"MM\x00*",
        b"II+\x00",
        b"MM\x00+",
        b"BM",
        b"\x00\x00\x01\x00",
        b"RIFF",
        b"v/1\x01",
        b"#?RADIANCE\n",
        b"P1\n",
        b"P2\n",
        b"P3\n",
        b"P4\n",
        b"P5\n",
        b"P6\n",
    ];
    if sigs.iter().any(|s| head.starts_with(s)) {
        return true;
    }
    // JPEG Exif
    if head[0..4] == [0xff, 0xd8, 0xff, 0xe1] && &head[6..12] == b"Exif\x00\x00" {
        return true;
    }
    false
}

fn is_binary(buf: &[u8]) -> bool {
    let boms: &[&[u8]] = &[
        b"\xef\xbb\xbf",
        b"\xff\xfe\x00\x00",
        b"\x00\x00\xfe\xff",
        b"\xff\xfe",
        b"\xfe\xff",
    ];
    if boms.iter().any(|b| buf.starts_with(b)) {
        return false;
    }
    let n = buf.len().min(1024);
    if buf[..n].contains(&0) {
        return true;
    }
    if buf.starts_with(b"\x89PNG") || buf.starts_with(b"%PDF") {
        return true;
    }
    false
}

pub fn text_lines(s: &str) -> Vec<String> {
    s.split('\n')
        .map(|l| {
            l.replace('\t', "    ")
                .chars()
                .filter(|c| !c.is_control())
                .collect::<String>()
        })
        .collect()
}

pub fn dir_tree(dir: &Path, show_hidden: bool) -> Option<String> {
    let rd = std::fs::read_dir(dir).ok()?;
    let mut dirs = vec![];
    let mut files = vec![];
    for e in rd.flatten() {
        let name = e.file_name().to_string_lossy().into_owned();
        if !show_hidden && name.starts_with('.') {
            continue;
        }
        let is_dir = e.file_type().map(|t| t.is_dir()).unwrap_or(false);
        if is_dir {
            dirs.push(name);
        } else {
            files.push(name);
        }
    }
    dirs.sort_by(|a, b| natcmp(a, b, false));
    files.sort_by(|a, b| natcmp(a, b, false));
    dirs.extend(files);
    let n = dirs.len();
    let mut s = String::new();
    for (i, name) in dirs.iter().enumerate() {
        if i == n - 1 {
            s.push_str("└ ");
            s.push_str(name);
        } else {
            s.push_str("├ ");
            s.push_str(name);
            s.push('\n');
        }
    }
    Some(s)
}

pub fn file_content(path: &Path) -> Content {
    let mut f = match std::fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return Content::Plain("(file not readable)".to_string()),
    };
    match f.metadata() {
        Ok(m) if m.is_file() => {}
        Ok(_) => return Content::Nothing,
        Err(_) => return Content::Plain("(file not readable)".to_string()),
    }
    let mut buf = vec![];
    if f.read_to_end(&mut buf).is_err() {
        return Content::Plain("(file not readable)".to_string());
    }
    if is_image(&buf[..buf.len().min(12)]) {
        return Content::Image;
    }
    if is_binary(&buf) {
        return Content::Plain("(binary file)".to_string());
    }
    match String::from_utf8(buf) {
        Ok(s) => Content::Text(text_lines(&s)),
        Err(_) => Content::Nothing,
    }
}

/// Wrap a line to the given width.
pub fn wrap(line: &str, width: usize) -> Vec<String> {
    let mut out = vec![];
    let mut cur = String::new();
    let mut w = 0;
    for c in line.chars() {
        let cw = char_width(c);
        if w + cw > width && !cur.is_empty() {
            out.push(std::mem::take(&mut cur));
            w = 0;
        }
        cur.push(c);
        w += cw;
    }
    if !cur.is_empty() || out.is_empty() {
        out.push(cur);
    }
    out
}
