pub fn now_secs() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

pub fn copy_recursive(src: &Path, dest: &Path) -> std::io::Result<()> {
    let meta = std::fs::symlink_metadata(src)?;
    if meta.file_type().is_symlink() {
        let target = std::fs::read_link(src)?;
        std::os::unix::fs::symlink(target, dest)?;
        return Ok(());
    }
    if meta.is_dir() {
        std::fs::create_dir(dest)?;
        for e in std::fs::read_dir(src)? {
            let e = e?;
            copy_recursive(&e.path(), &dest.join(e.file_name()))?;
        }
        let _ = std::fs::set_permissions(dest, meta.permissions());
        Ok(())
    } else {
        std::fs::copy(src, dest)?;
        Ok(())
    }
}

pub fn remove_any(p: &Path) -> std::io::Result<()> {
    let meta = std::fs::symlink_metadata(p)?;
    if meta.is_dir() {
        std::fs::remove_dir_all(p)
    } else {
        std::fs::remove_file(p)
    }
}

pub fn move_any(src: &Path, dest: &Path) -> std::io::Result<()> {
    match std::fs::rename(src, dest) {
        Ok(_) => Ok(()),
        Err(e) => {
            if e.raw_os_error() == Some(libc::EXDEV) {
                copy_recursive(src, dest)?;
                remove_any(src)
            } else {
                Err(e)
            }
        }
    }
}

pub fn exists(p: &Path) -> bool {
    std::fs::symlink_metadata(p).is_ok()
}

/// Unique destination name for put.
pub fn unique_put_path(dir: &Path, name: &str, is_dir: bool) -> PathBuf {
    let first = dir.join(name);
    if !exists(&first) {
        return first;
    }
    let p = Path::new(name);
    let mut n = 1;
    loop {
        let candidate = if is_dir {
            format!("{}_{}", name, n)
        } else {
            match (p.file_stem(), p.extension()) {
                (Some(stem), Some(ext)) => format!(
                    "{}_{}.{}",
                    stem.to_string_lossy(),
                    n,
                    ext.to_string_lossy()
                ),
                _ => format!("{}_{}", name, n),
            }
        };
        let c = dir.join(candidate);
        if !exists(&c) {
            return c;
        }
        n += 1;
    }
}

/// Unique destination for unpack: name_1, name_2...
pub fn unique_suffix_path(dir: &Path, name: &str) -> PathBuf {
    let first = dir.join(name);
    if !exists(&first) {
        return first;
    }
    let mut n = 1;
    loop {
        let c = dir.join(format!("{}_{}", name, n));
        if !exists(&c) {
            return c;
        }
        n += 1;
    }
}

/// Move item to trash; returns trash path.
pub fn to_trash(src: &Path, trash_dir: &Path) -> std::io::Result<PathBuf> {
    let name = src
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let base = format!("{}_{}", now_secs(), name);
    let mut dest = trash_dir.join(&base);
    let mut n = 1;
    while exists(&dest) {
        dest = trash_dir.join(format!("{}_{}", base, n));
        n += 1;
    }
    move_any(src, &dest)?;
    Ok(dest)
}
