}

impl Paths {
    pub fn new() -> Paths {
        let config_dir = xdg("XDG_CONFIG_HOME", ".config").join("felix");
        let data_dir = xdg("XDG_DATA_HOME", ".local/share").join("felix");
        Paths {
            trash_dir: data_dir.join("Trash"),
            session_path: data_dir.join(".session"),
            log_dir: data_dir.join("log"),
            config_dir,
            data_dir,
        }
    }
}

#[derive(Clone, Debug)]
pub struct RegItem {
    /// path where the item currently lives (original or trash)
    pub path: PathBuf,
    /// original file name
    pub name: String,
    pub is_dir: bool,
}

#[derive(Clone, Debug)]
pub enum Op {
    Put { created: Vec<PathBuf>, sources: Vec<RegItem>, dir: PathBuf },
    Delete { moved: Vec<(PathBuf, PathBuf)> },
    Rename { pairs: Vec<(PathBuf, PathBuf)> },
}

pub struct Registers {
    pub unnamed: Vec<RegItem>,
    pub zero: Vec<RegItem>,
    pub numbered: Vec<Vec<RegItem>>, // index 0 => "1
    pub named: std::collections::BTreeMap<char, Vec<RegItem>>,
}

impl Registers {
    fn new() -> Self {
        Registers {
            unnamed: vec![],
            zero: vec![],
            numbered: vec![],
            named: Default::default(),
        }
    }
}

pub enum Pending {
    None,
}

pub struct App {
    pub out: Out,
    pub paths: Paths,
    pub config: Config,
    pub session: Session,
    pub cwd: PathBuf,
    pub list: Vec<Item>,
    pub idx: usize,
    pub y: usize,
    pub skip: usize,
    pub w: usize,
    pub h: usize,
    pub branch: Option<String>,
    pub readonly: bool,
    pub keyword: Option<String>,
    pub preview_scroll: usize,
    pub show_reg: bool,
    pub regs: Registers,
    pub undo: Vec<Op>,
    pub redo: Vec<Op>,
    pub jumps: Vec<PathBuf>,
    pub jump_pos: usize,
    pub child_mem: HashMap<PathBuf, (PathBuf, usize, usize)>,
    pub visual: Option<usize>,
    pub log: bool,
    pub quit: bool,
}

pub fn start(path: PathBuf, log: bool) {
    let paths = Paths::new();
    let _ = std::fs::create_dir_all(&paths.config_dir);
    let _ = std::fs::create_dir_all(&paths.trash_dir);
    if log {
        logger::init(&paths.log_dir);
        logger::info("===START===");
    }
    let config = Config::load(&paths.config_dir);
    let session = Session::load(&paths.session_path);
    let (w, h) = terminal_size();
    let mut app = App {
        out: Out::new(),
        paths,
        config,
        session,
        cwd: path.clone(),
        list: vec![],
        idx: 0,
        y: 0,
        skip: 0,
        w,
        h,
        branch: None,
        readonly: false,
        keyword: None,
        preview_scroll: 0,
        show_reg: false,
        regs: Registers::new(),
        undo: vec![],
        redo: vec![],
        jumps: vec![path.clone()],
        jump_pos: 0,
        child_mem: HashMap::new(),
        visual: None,
        log,
        quit: false,
    };
    let _ = crossterm::terminal::enable_raw_mode();
    app.out.s("\x1b7\x1b[?25l\x1b[?1049h");
    let _ = std::env::set_current_dir(&path);
    app.load_dir();
    app.redraw();
    app.out.flush();
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| app.run()));
    match res {
        Ok(_) => {
            app.out.s("\x1b[?25l\x1b[?1049l\x1b8\x1b[?25h");
            app.out.flush();
            let _ = crossterm::terminal::disable_raw_mode();
            if log {
                logger::info("===FINISH===");
            }
        }
        Err(e) => {
            let msg = if let Some(s) = e.downcast_ref::<String>() {
                s.clone()
            } else if let Some(s) = e.downcast_ref::<&str>() {
                s.to_string()
            } else {
                "panicked".to_string()
            };
            let mut o = Out::new();
            o.s("\x1b[?25h\x1b[2J\x1b[1;1H");
            o.s(&format!("Panic: {}\r\nError: felix panicked\r\n", msg));
            o.flush();
            let _ = crossterm::terminal::disable_raw_mode();
        }
    }
}
