// ---------------------------------------------------------------- layout
impl App {
    pub fn vertical_preview(&self) -> bool {
        self.session.preview && self.session.split == Split::Vertical
    }
    pub fn horizontal_preview(&self) -> bool {
        self.session.preview && self.session.split == Split::Horizontal
    }
    /// list width
    pub fn lw(&self) -> usize {
        if self.vertical_preview() {
            self.w / 2
        } else {
            self.w
        }
    }
    /// footer row (1-based)
    pub fn lb(&self) -> usize {
        if self.horizontal_preview() {
            self.h / 2
        } else {
            self.h
        }
    }
    pub fn rows(&self) -> usize {
        self.lb().saturating_sub(3)
    }
    pub fn show_time(&self) -> bool {
        self.lw() >= 28
    }
    pub fn name_area(&self) -> usize {
        if self.show_time() {
            self.lw() - 19
        } else {
            self.lw().saturating_sub(2)
        }
    }
    pub fn cur(&self) -> Option<&Item> {
        self.list.get(self.idx)
    }
    pub fn preview_col(&self) -> usize {
        // 1-based column for preview text
        if self.vertical_preview() {
            self.lw() + 2
        } else {
            1
        }
    }
    pub fn preview_row(&self) -> usize {
        if self.vertical_preview() {
            3
        } else {
            self.lb() + 2
        }
    }
    pub fn preview_width(&self) -> usize {
        if self.vertical_preview() {
            self.w.saturating_sub(self.lw() + 1)
        } else {
            self.w
        }
    }
    pub fn preview_height(&self) -> usize {
        if self.vertical_preview() {
            self.h.saturating_sub(3)
        } else {
            self.h.saturating_sub(self.lb() + 2)
        }
    }
}

// ---------------------------------------------------------------- drawing
impl App {
    pub fn header(&mut self) {
        let lw = self.lw();
        let path = format!(" {}", self.cwd.display());
        let path = truncate_width(&path, lw);
        self.out.mv(1, 1);
        self.out.fg(&Color::Ansi(6));
        self.out.s(&path);
        self.out.reset();
        if self.readonly {
            self.out.fg(&Color::Ansi(1));
            self.out.s(" [RO]");
            self.out.reset();
        }
        if let Some(b) = self.branch.clone() {
            self.out.s(" on ");
            self.out.fg(&Color::Ansi(13));
            self.out.bold();
            self.out.s(&b);
            self.out.reset();
            self.out.reset();
        }
    }

    fn item_color(&self, it: &Item) -> Color {
        if it.dirty {
            return self.config.colors.dirty.clone();
        }
        match it.ftype {
            FileType::Directory => self.config.colors.dir.clone(),
            FileType::File => self.config.colors.file.clone(),
            FileType::Symlink => self.config.colors.symlink.clone(),
        }
    }

    pub fn draw_items(&mut self) {
        let rows = self.rows();
        let lw = self.lw();
        let area = self.name_area();
        let show_time = self.show_time();
        let end = (self.skip + rows).min(self.list.len());
        for i in self.skip..end {
            let row = 3 + (i - self.skip);
            let it = &self.list[i];
            let color = self.item_color(it);
            let name = shorten_name(&it.name, area);
            let time = it.mtime.clone().unwrap_or_default();
            let selected = it.selected;
            let matches = it.matches && self.visual.is_none();
            self.out.mv(3, row);
            self.out.fg(&color);
            if selected {
                self.out.reverse();
                self.out.s(&name);
                self.out.reset();
                if show_time {
                    self.out.left(1000);
                    self.out.right(lw - 17);
                    self.out.s(" ");
                    self.out.reverse();
                    self.out.s(&time);
                    self.out.reset();
                }
                self.out.reset();
            } else if matches {
                self.out.bold();
                self.out.s(&name);
                self.out.reset();
                if show_time {
                    self.out.left(1000);
                    self.out.right(lw - 17);
                    self.out.fg(&color);
                    self.out.s(" ");
                    self.out.s(&time);
                }
                self.out.reset();
            } else {
                self.out.s(&name);
                if show_time {
                    self.out.left(1000);
                    self.out.right(lw - 17);
                    self.out.s(" ");
                    self.out.s(&time);
                }
                self.out.reset();
            }
        }
    }

    pub fn list_redraw(&mut self) {
        self.out.clear_all();
        self.out.mv(1, 1);
        self.header();
        self.draw_items();
    }

    pub fn unprint_cursor(&mut self) {
        self.out.s(" \x1b[1D");
    }

    pub fn print_cursor(&mut self) {
        let row = 3 + self.y;
        self.out.mv(1, row);
        self.out.s(">\x1b[1D");
    }

    pub fn match_count(&self) -> usize {
        self.list.iter().filter(|i| i.matches).count()
    }

    pub fn footer(&mut self) {
        let lb = self.lb();
        let lw = self.lw();
        self.out.mv(1, lb);
        self.out.clear_line();
        self.out.reset();
        self.out.reverse();
        self.out.s(&" ".repeat(lw));
        self.out.reset();
        self.out.mv(1, lb);
        if let Some(kw) = self.keyword.clone() {
            self.out.reverse();
            self.out.s(&" ".repeat(lw));
            self.out.reset();
            self.out.mv(1, lb);
            let n = self.match_count();
            self.out.reverse();
            self.out.s(" /");
            self.out.reset();
            self.out.reverse();
            self.out.s(&kw);
            self.out.reset();
            self.out.reverse();
            self.out.s(" - ");
            self.out.reset();
            self.out.reverse();
            self.out.s(&format!("{} match{}", n, if n > 1 { "es" } else { "" }));
            self.out.reset();
        } else if let Some(it) = self.cur() {
            let text = it.footer(self.idx, self.list.len());
            let text = truncate_width(&text, lw);
            self.out.reverse();
            self.out.s(&text);
            self.out.reset();
        }
    }

    pub fn update(&mut self) {
        self.unprint_cursor();
        self.footer();
        self.draw_preview();
        self.print_cursor();
    }

    pub fn redraw(&mut self) {
        self.list_redraw();
        self.update();
    }

    pub fn print_info(&mut self, msg: &str) {
        if self.log {
            logger::info(msg);
        }
        self.unprint_cursor();
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.s(msg);
        self.out.hide();
        self.print_cursor();
    }

    pub fn print_error(&mut self, msg: &str) {
        if self.log {
            logger::info(msg);
        }
        self.unprint_cursor();
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.fg(&Color::Ansi(7));
        self.out.bg(&Color::Ansi(9));
        self.out.s(msg);
        self.out.reset();
        self.out.hide();
        self.print_cursor();
    }

    pub fn print_process(&mut self, msg: &str) {
        self.unprint_cursor();
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.s(msg);
    }

    pub fn clear_status(&mut self) {
        self.out.mv(2, 2);
        self.out.clear_line();
    }

    fn preview_clear(&mut self) {
        let col = self.preview_col();
        let row = self.preview_row();
        let lb = self.lb();
        for i in 0..=lb {
            self.out.mv(col, row + i);
            self.out.clear_eol();
        }
        self.out.mv(col, row);
    }

    fn draw_lines(&mut self, lines: &[String], grey: bool) {
        let col = self.preview_col();
        let row = self.preview_row();
        let pw = self.preview_width();
        let ph = self.preview_height();
        let mut rows: Vec<String> = vec![];
        for l in lines {
