                rows.push(seg);
            }
            if rows.len() > self.preview_scroll + ph + 1 {
                break;
            }
        }
        let start = self.preview_scroll.min(rows.len());
        let mut printed = 0;
        for (k, seg) in rows[start..].iter().enumerate() {
            if k >= ph {
                break;
            }
            self.out.mv(col, row + k);
            if grey {
                self.out.fg(&Color::Ansi(8));
            }
            self.out.s(seg);
            printed += 1;
        }
        if grey && (printed > 0 || !rows.is_empty()) {
            self.out.reset();
        }
    }

    pub fn draw_preview(&mut self) {
        if !self.session.preview {
            return;
        }
        if self.show_reg {
            self.draw_registers();
            return;
        }
        if self.vertical_preview() {
            let lw = self.lw();
            let pw = self.preview_width();
            self.out.mv(lw + 1, 1);
            self.out.clear_eol();
            self.out.right(1);
            if let Some(it) = self.cur() {
                let title = format!("[{}]", it.name);
                let title = truncate_width(&title, pw);
                self.out.s(&title);
            }
        }
        self.preview_clear();
        let it = match self.cur() {
            Some(i) => i.clone(),
            None => return,
        };
        let content = if it.is_dir_like {
            match preview::dir_tree(&it.path, self.session.show_hidden) {
                Some(s) => Content::Text(s.split('\n').map(|x| x.to_string()).collect()),
                None => Content::Nothing,
            }
        } else {
            preview::file_content(&it.path)
        };
        match content {
            Content::Text(lines) => self.draw_lines(&lines, true),
            Content::Plain(s) => self.out.s(&s),
            Content::Image => {
                let lines = vec![preview::IMAGE_MSG.to_string()];
                self.draw_lines(&lines, false);
            }
            Content::Nothing => {}
        }
    }

    pub fn draw_registers(&mut self) {
        self.preview_clear();
        let mut lines: Vec<String> = vec![];
        let names = |v: &Vec<RegItem>| -> String {
            v.iter().map(|r| r.name.clone()).collect::<Vec<_>>().join(" ")
        };
        if !self.regs.unnamed.is_empty() {
            lines.push(format!("\"\" {}", names(&self.regs.unnamed)));
        }
        if !self.regs.zero.is_empty() {
            lines.push(format!("\"0 {}", names(&self.regs.zero)));
        }
        for (i, v) in self.regs.numbered.iter().enumerate() {
            if !v.is_empty() {
                lines.push(format!("\"{} {}", i + 1, names(v)));
            }
        }
        for (c, v) in self.regs.named.iter() {
            if !v.is_empty() {
                lines.push(format!("\"{} {}", c, names(v)));
            }
        }
        let col = self.preview_col();
        let row = self.preview_row();
        let pw = self.preview_width();
        let ph = self.preview_height();
        let mut k = 0;
        for l in lines {
            for seg in preview::wrap(&l, pw.max(1)) {
                if k >= ph {
                    break;
                }
                self.out.mv(col, row + k);
                self.out.s(&seg);
                k += 1;
            }
        }
    }
