fn is_writable(p: &Path) -> bool {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    match CString::new(p.as_os_str().as_bytes()) {
        Ok(c) => unsafe { libc::access(c.as_ptr(), libc::W_OK) == 0 },
        Err(_) => false,
    }
}

impl App {
    pub fn load_dir(&mut self) {
        let dirty = crate::git::dirty_paths(&self.cwd);
        self.list = item::list_dir(
            &self.cwd,
            self.session.show_hidden,
            self.session.sort_by,
            &dirty,
        )
        .unwrap_or_default();
        self.branch = crate::git::branch(&self.cwd);
        self.readonly = !is_writable(&self.cwd);
        if let Some(kw) = self.keyword.clone() {
            self.mark_matches(&kw);
        }
    }

    pub fn mark_matches(&mut self, kw: &str) {
        let ic = self.config.ignore_case;
        let kwl = kw.to_lowercase();
        for it in self.list.iter_mut() {
            it.matches = if ic {
                it.name.to_lowercase().contains(&kwl)
            } else {
                it.name.contains(kw)
            };
        }
    }

    pub fn clear_matches(&mut self) {
        for it in self.list.iter_mut() {
            it.matches = false;
        }
    }

    /// Reload current directory keeping cursor index (clamped).
    pub fn reload_keep(&mut self) {
        self.load_dir();
        self.clamp_cursor();
    }

    pub fn clamp_cursor(&mut self) {
        let len = self.list.len();
        if len == 0 {
            self.idx = 0;
            self.y = 0;
            self.skip = 0;
            return;
        }
        if self.idx > len - 1 {
            self.idx = len - 1;
            if self.idx >= self.skip {
                self.y = self.idx - self.skip;
            } else {
                self.y = self.idx.min(3);
                self.skip = self.idx - self.y;
            }
        }
    }

    pub fn reset_cursor(&mut self) {
        self.idx = 0;
        self.y = 0;
        self.skip = 0;
    }

    /// Change to a directory. cursor: Some((idx,y)) or top.
    pub fn chdir(&mut self, p: &Path, cursor: Option<(usize, usize)>) {
        self.cwd = p.to_path_buf();
        let _ = std::env::set_current_dir(p);
        self.keyword = None;
        self.preview_scroll = 0;
        self.load_dir();
        match cursor {
            Some((i, y)) => {
                self.idx = i;
                self.y = y;
                self.skip = i.saturating_sub(y);
                self.clamp_cursor();
            }
            None => self.reset_cursor(),
        }
    }

    pub fn push_jump(&mut self, p: &Path) {
        self.jumps.truncate(self.jump_pos + 1);
        self.jumps.push(p.to_path_buf());
        self.jump_pos = self.jumps.len() - 1;
    }

    pub fn go_down(&mut self) -> bool {
        // returns true if full redraw needed
        let len = self.list.len();
        if len == 0 || self.idx == len - 1 {
            return false;
        }
        let rows = self.rows() as isize;
        if (self.y as isize) >= rows - 4 && (len as isize) > rows - 1 {
            self.skip += 1;
            self.idx += 1;
            true
        } else {
            self.y += 1;
            self.idx += 1;
            false
        }
    }

    pub fn go_up(&mut self) -> bool {
        if self.idx == 0 {
            return false;
        }
        if self.y <= 3 && self.skip > 0 {
            self.skip -= 1;
            self.idx -= 1;
            true
        } else {
            self.y = self.y.saturating_sub(1);
            self.idx -= 1;
            false
        }
    }

    pub fn go_bottom(&mut self) {
        let len = self.list.len();
        if len == 0 {
            return;
        }
        let rows = self.rows();
        self.idx = len - 1;
        if len > rows {
            self.skip = len - rows;
            self.y = rows.saturating_sub(1);
        } else {
            self.skip = 0;
            self.y = len - 1;
        }
    }

    /// position cursor at index with the "parent" rule (y = min(idx,3))
    pub fn put_cursor_at(&mut self, i: usize) {
        self.idx = i;
        self.y = i.min(3);
        self.skip = i - self.y;
    }

    pub fn after_layout_change(&mut self) {
        let rows = self.rows();
        if rows > 0 && self.y > rows - 1 {
            self.y = rows - 1;
        }
        self.idx = self.skip + self.y;
        let len = self.list.len();
        if len > 0 && self.idx > len - 1 {
            self.idx = len - 1;
            self.y = self.idx.saturating_sub(self.skip);
        }
    }
}
