// ---------------------------------------------------------------- key helpers
pub fn is_char(k: &KeyEvent, c: char) -> bool {
    k.code == KeyCode::Char(c)
        && !k.modifiers.intersects(KeyModifiers::CONTROL | KeyModifiers::ALT)
}

pub fn is_ctrl(k: &KeyEvent, c: char) -> bool {
    k.code == KeyCode::Char(c) && k.modifiers.contains(KeyModifiers::CONTROL)
}

pub fn is_alt(k: &KeyEvent, c: char) -> bool {
    k.code == KeyCode::Char(c) && k.modifiers.contains(KeyModifiers::ALT)
}

pub fn plain_char(k: &KeyEvent) -> Option<char> {
    match k.code {
        KeyCode::Char(c) if !k.modifiers.intersects(KeyModifiers::CONTROL | KeyModifiers::ALT) => {
            Some(c)
        }
        _ => None,
    }
}

impl App {
    /// Read the next key press (nested read). Resize events update the size.
    pub fn next_key(&mut self) -> KeyEvent {
        self.out.flush();
        loop {
            match event::read() {
                Ok(Event::Key(k)) => {
                    if k.kind == KeyEventKind::Press || k.kind == KeyEventKind::Repeat {
                        return k;
                    }
                }
                Ok(Event::Resize(w, h)) => {
                    self.w = w as usize;
                    self.h = h as usize;
                }
                Ok(_) => {}
                Err(_) => {
                    return KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE);
                }
            }
        }
    }

    pub fn run(&mut self) {
        while !self.quit {
            self.out.flush();
            let ev = match event::read() {
                Ok(e) => e,
                Err(_) => break,
            };
            match ev {
                Event::Key(k) => {
                    if k.kind != KeyEventKind::Press && k.kind != KeyEventKind::Repeat {
                        continue;
                    }
                    self.normal_key(k);
                }
                Event::Resize(w, h) => {
                    self.w = w as usize;
                    self.h = h as usize;
                    self.after_layout_change();
                    self.redraw();
                }
                _ => {}
            }
        }
        self.out.flush();
    }

    pub fn move_and_draw(&mut self, full: bool) {
        if full {
            self.redraw();
        } else {
            self.update();
        }
    }
}
