// ---------------------------------------------------------------- normal mode
impl App {
    pub fn normal_key(&mut self, k: KeyEvent) {
        let code = k.code;
        let m = k.modifiers;
        let ctrl = m.contains(KeyModifiers::CONTROL);
        let alt = m.contains(KeyModifiers::ALT);
        if alt {
            match code {
                KeyCode::Char('j') | KeyCode::Down => self.preview_scroll_down(),
                KeyCode::Char('k') | KeyCode::Up => self.preview_scroll_up(),
                _ => {}
            }
            return;
        }
        if ctrl {
            match code {
                KeyCode::Char('d') => self.half_page(true),
                KeyCode::Char('u') => self.half_page(false),
                KeyCode::Char('o') => self.jump_back(),
                KeyCode::Char('r') => self.do_redo(),
                _ => {}
            }
            return;
        }
        match code {
            KeyCode::Char('j') | KeyCode::Down => {
                if self.list.is_empty() {
                    self.redraw();
                    return;
                }
                let full = self.go_down();
                self.preview_scroll = 0;
                self.move_and_draw(full);
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if self.list.is_empty() {
                    self.redraw();
                    return;
                }
                let full = self.go_up();
                self.preview_scroll = 0;
                self.move_and_draw(full);
            }
            KeyCode::Char('h') | KeyCode::Left => self.go_parent(),
            KeyCode::Char('l') | KeyCode::Right | KeyCode::Enter => self.open_item(),
            KeyCode::Tab => self.jump_forward(),
            KeyCode::Char('g') => self.key_g(),
            KeyCode::Char('G') => {
                if self.list.is_empty() {
                    return;
                }
                self.go_bottom();
                self.preview_scroll = 0;
                self.redraw();
            }
            KeyCode::Char('z') => self.key_z(),
            KeyCode::Char('i') => self.create_item(false),
            KeyCode::Char('I') => self.create_item(true),
            KeyCode::Char('o') => self.open_new_window(),
            KeyCode::Char('e') => self.unpack_item(),
            KeyCode::Char('d') => self.key_d(),
            KeyCode::Char('y') => self.key_y(),
            KeyCode::Char('p') => self.put_from(None),
            KeyCode::Char('"') => self.key_register(),
            KeyCode::Char('V') => self.visual_mode(),
            KeyCode::Char('u') => self.do_undo(),
            KeyCode::Char('v') => self.toggle_preview(),
            KeyCode::Char('s') => self.toggle_split(),
            KeyCode::Backspace => self.toggle_hidden(),
            KeyCode::Char('t') => self.toggle_sort(),
            KeyCode::Char('c') => self.rename_item(),
            KeyCode::Char('/') => self.search_mode(),
            KeyCode::Char('n') => self.search_next(true),
            KeyCode::Char('N') => self.search_next(false),
            KeyCode::Char(':') => self.command_mode(),
            KeyCode::Esc => self.redraw(),
            KeyCode::Char('Z') => self.key_zz(),
            _ => {}
        }
    }

    fn half_page(&mut self, down: bool) {
        if self.list.is_empty() {
            return;
        }
        let n = (self.h + 1) / 2;
        let mut full = false;
        for _ in 0..n {
            if down {
                full |= self.go_down();
            } else {
                full |= self.go_up();
            }
        }
        self.preview_scroll = 0;
        self.move_and_draw(full);
    }

    fn preview_scroll_down(&mut self) {
        if !self.session.preview {
            return;
        }
        self.preview_scroll += 1;
        self.update();
    }

    fn preview_scroll_up(&mut self) {
        if !self.session.preview {
            return;
        }
        if self.preview_scroll > 0 {
            self.preview_scroll -= 1;
        }
        self.update();
    }

    fn key_g(&mut self) {
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.s("g");
        self.out.show();
        let k = self.next_key();
        if is_char(&k, 'g') {
            self.out.hide();
            self.reset_cursor();
            self.preview_scroll = 0;
            self.redraw();
        } else {
            self.out.hide();
            self.out.clear_line();
            self.update();
        }
    }

    pub fn go_parent(&mut self) {
        let parent = match self.cwd.parent() {
            Some(p) => p.to_path_buf(),
            None => return,
        };
        let child = self.cwd.clone();
        self.child_mem
            .insert(parent.clone(), (child.clone(), self.idx, self.y));
        let mem = self.enter_mem.get(&child).cloned();
        self.chdir(&parent, None);
        let mut placed = false;
        if let Some((p, i, y)) = mem {
            if p == parent && i < self.list.len() {
                self.idx = i;
                self.y = y;
                self.skip = i.saturating_sub(y);
                placed = true;
            }
        }
        if !placed {
            let name = child
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_default();
            if let Some(i) = self.list.iter().position(|it| it.name == name) {
                self.put_cursor_at(i);
            }
        }
        self.push_jump(&parent);
        self.redraw();
    }

    pub fn enter_dir(&mut self, target: PathBuf) {
        let from = self.cwd.clone();
        let target = std::fs::canonicalize(&target).unwrap_or(target);
        if std::fs::read_dir(&target).is_err() {
            match std::fs::read_dir(&target) {
                Err(e) => {
                    let msg = e.to_string();
                    self.print_error(&msg);
                }
                Ok(_) => {}
            }
            return;
        }
        self.enter_mem
            .insert(target.clone(), (from.clone(), self.idx, self.y));
        let mem = self.child_mem.get(&from).cloned();
        self.chdir(&target, None);
        if let Some((c, i, y)) = mem {
            if c == target && i < self.list.len() {
                self.idx = i;
                self.y = y;
                self.skip = i.saturating_sub(y);
            }
        }
        self.push_jump(&target);
        self.redraw();
    }

    pub fn open_item(&mut self) {
        let it = match self.cur() {
            Some(i) => i.clone(),
            None => return,
        };
        if it.is_dir_like {
            self.enter_dir(it.path.clone());
        } else {
            self.open_file(&it);
        }
    }

    pub fn jump_back(&mut self) {
        if self.jump_pos == 0 {
            return;
        }
        let target = self.jumps[self.jump_pos - 1].clone();
        if !target.is_dir() {
            return;
        }
        self.jump_pos -= 1;
        self.chdir(&target, None);
        self.redraw();
    }

    pub fn jump_forward(&mut self) {
        if self.jump_pos + 1 >= self.jumps.len() {
            return;
        }
        let target = self.jumps[self.jump_pos + 1].clone();
        if !target.is_dir() {
            return;
        }
        self.jump_pos += 1;
        self.chdir(&target, None);
        self.redraw();
    }

    fn toggle_preview(&mut self) {
        self.session.preview = !self.session.preview;
        self.show_reg = false;
        self.preview_scroll = 0;
        self.after_layout_change();
        self.redraw();
    }

    fn toggle_split(&mut self) {
        self.session.split = match self.session.split {
            Split::Vertical => Split::Horizontal,
            Split::Horizontal => Split::Vertical,
        };
        self.after_layout_change();
        self.redraw();
    }

    fn toggle_hidden(&mut self) {
        self.session.show_hidden = !self.session.show_hidden;
        self.load_dir();
        self.reset_cursor();
        self.redraw();
    }

    fn toggle_sort(&mut self) {
        self.session.sort_by = match self.session.sort_by {
            SortKey::Name => SortKey::Time,
            SortKey::Time => SortKey::Name,
        };
        item::resort(&mut self.list, self.session.sort_by);
        self.reset_cursor();
        self.redraw();
    }

    fn key_z(&mut self) {
        let has = std::process::Command::new("zoxide")
            .arg("--version")
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .is_ok();
        if !has {
            self.print_error("zoxide not found.");
            return;
        }
        // zoxide mode
        let mut buf: Vec<char> = vec![];
        let prompt = "z";
        match self.line_input(prompt, &mut buf, true) {
            Some(s) => {
                let s = s.trim().to_string();
                if s.is_empty() {
                    let home = home_dir();
                    self.chdir(&home, None);
                    self.push_jump(&home);
                    self.redraw();
                    return;
                }
                let out = std::process::Command::new("zoxide")
                    .arg("query")
                    .args(s.split_whitespace())
                    .output();
                match out {
                    Ok(o) if o.status.success() => {
                        let p = String::from_utf8_lossy(&o.stdout).trim().to_string();
                        let pb = PathBuf::from(p);
                        if pb.is_dir() {
                            self.chdir(&pb, None);
                            self.push_jump(&pb);
                            self.redraw();
                        } else {
                            self.redraw();
                        }
                    }
                    _ => {
                        self.redraw();
                        self.print_error("No match found.");
                    }
                }
            }
            None => {
                self.redraw();
            }
        }
    }

    fn key_zz(&mut self) {
        self.unprint_cursor();
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.s("Z");
        self.out.show();
        let k = self.next_key();
        let zz = is_char(&k, 'Z');
        let zq = is_char(&k, 'Q');
        if zz || zq {
            let write_lwd = if self.config.match_vim_exit_behavior { zz } else { zq };
            if write_lwd {
                if let Err(msg) = self.write_lwd() {
                    self.out.mv(2, 2);
                    self.out.clear_line();
                    self.out.hide();
                    self.update();
                    self.print_error(&msg);
                    return;
                }
            }
            self.exit_app();
            return;
        }
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.hide();
        self.update();
    }

    fn write_lwd(&mut self) -> Result<(), String> {
        let pid = match std::env::var("SHELL_PID") {
            Ok(p) => p,
            Err(_) => return Err("Shell integration may not be configured.".to_string()),
        };
        let base = if let Some(v) = std::env::var_os("XDG_RUNTIME_DIR").filter(|v| !v.is_empty()) {
            PathBuf::from(v).join("felix")
        } else if let Some(v) = std::env::var_os("TMPDIR").filter(|v| !v.is_empty()) {
            PathBuf::from(v).join("felix")
        } else {
            PathBuf::from("/tmp/felix")
        };
        let _ = std::fs::create_dir_all(&base);
        std::fs::write(base.join(pid), self.cwd.as_os_str().as_encoded_bytes())
            .map_err(|e| e.to_string())
    }

    pub fn exit_app(&mut self) {
        self.session.save(&self.paths.session_path);
        self.quit = true;
    }
}
