        self.session.preview = !self.session.preview;
        self.show_reg = false;
        self.preview_scroll = 0;
        self.after_layout_change();
        self.redraw();
    }

    fn toggle_split(&mut self) {
        self.session.split = match self.session.split {
            Split::Vertical => Split::Horizontal,
            Split::Horizontal => Split::Vertical,
        };
        self.after_layout_change();
        self.redraw();
    }

    fn toggle_hidden(&mut self) {
        self.session.show_hidden = !self.session.show_hidden;
        self.load_dir();
        self.reset_cursor();
        self.redraw();
    }

    fn toggle_sort(&mut self) {
        self.session.sort_by = match self.session.sort_by {
            SortKey::Name => SortKey::Time,
            SortKey::Time => SortKey::Name,
        };
        item::resort(&mut self.list, self.session.sort_by);
        self.reset_cursor();
        self.redraw();
    }

    fn key_z(&mut self) {
        let has = std::process::Command::new("zoxide")
            .arg("--version")
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .is_ok();
        if !has {
            self.print_error("zoxide not found.");
            return;
        }
        // zoxide mode
        let mut buf: Vec<char> = vec![];
        let prompt = "z";
        match self.line_input(prompt, &mut buf, true) {
            Some(s) => {
                let s = s.trim().to_string();
                if s.is_empty() {
                    let home = home_dir();
                    self.chdir(&home, None);
                    self.push_jump(&home);
                    self.redraw();
                    return;
                }
                let out = std::process::Command::new("zoxide")
                    .arg("query")
                    .args(s.split_whitespace())
                    .output();
                match out {
                    Ok(o) if o.status.success() => {
                        let p = String::from_utf8_lossy(&o.stdout).trim().to_string();
                        let pb = PathBuf::from(p);
                        if pb.is_dir() {
                            self.chdir(&pb, None);
                            self.push_jump(&pb);
                            self.redraw();
                        } else {
                            self.redraw();
                        }
                    }
                    _ => {
                        self.redraw();
                        self.print_error("No match found.");
                    }
                }
            }
            None => {
                self.redraw();
            }
        }
    }

    fn key_zz(&mut self) {
        self.unprint_cursor();
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.s("Z");
        self.out.show();
        let k = self.next_key();
        let zz = is_char(&k, 'Z');
        let zq = is_char(&k, 'Q');
        if zz || zq {
            let write_lwd = if self.config.match_vim_exit_behavior { zz } else { zq };
            if write_lwd {
                if let Err(msg) = self.write_lwd() {
                    self.out.mv(2, 2);
                    self.out.clear_line();
                    self.out.hide();
                    self.update();
                    self.print_error(&msg);
                    return;
                }
            }
            self.exit_app();
            return;
        }
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.hide();
        self.update();
    }

    fn write_lwd(&mut self) -> Result<(), String> {
        let pid = match std::env::var("SHELL_PID") {
            Ok(p) => p,
            Err(_) => return Err("Shell integration may not be configured.".to_string()),
        };
        let base = if let Some(v) = std::env::var_os("XDG_RUNTIME_DIR").filter(|v| !v.is_empty()) {
            PathBuf::from(v).join("felix")
        } else if let Some(v) = std::env::var_os("TMPDIR").filter(|v| !v.is_empty()) {
            PathBuf::from(v).join("felix")
        } else {
            PathBuf::from("/tmp/felix")
        };
        let _ = std::fs::create_dir_all(&base);
        std::fs::write(base.join(pid), self.cwd.as_os_str().as_encoded_bytes())
            .map_err(|e| e.to_string())
    }

    pub fn exit_app(&mut self) {
        self.session.save(&self.paths.session_path);
        self.quit = true;
    }
}
