                        *cursor -= 1;
                        col -= 1;
                        self.out.left(1);
                    }
                    continue;
                }
                KeyCode::Right => {
                    if *cursor < text.len() {
                        *cursor += 1;
                        col += 1;
                        self.out.right(1);
                    }
                    continue;
                }
