                    if *cursor == 0 {
                        continue;
                    }
                    *cursor -= 1;
                    text.remove(*cursor);
                    col -= 1;
                }
                KeyCode::Char('h') if k.modifiers.contains(KeyModifiers::CONTROL) => {
                    if *cursor == 0 {
                        continue;
                    }
                    *cursor -= 1;
                    text.remove(*cursor);
                    col -= 1;
                }
                KeyCode::Char('r') if k.modifiers.contains(KeyModifiers::CONTROL) => {
                    // paste register
                    let k2 = self.next_key();
                    let rc = match plain_char(&k2) {
                        Some(c) => c,
