                    } else if rc == '0' {
                        self.regs.zero.clone()
                    } else if rc.is_ascii_digit() {
                        let n = (rc as u8 - b'1') as usize;
                        self.regs.numbered.get(n).cloned().unwrap_or_default()
                    } else if rc.is_ascii_alphabetic() {
                        self.regs
                            .named
                            .get(&rc.to_ascii_lowercase())
                            .cloned()
                            .unwrap_or_default()
                    } else {
