                app.y = 0;
            }
            app.preview_scroll = 0;
            app.redraw();
        };
        let res = self.edit_line("/", &mut text, &mut cur, 3, Some(&mut f));
        match res {
            InputResult::Done(kw) => {
                self.keyword = Some(kw);
                self.clear_status();
                self.update();
                self.out.hide();
            }
            InputResult::Cancel => {
                let kw: String = text.iter().collect();
                let _ = kw;
                self.redraw();
                self.out.hide();
            }
        }
    }

    fn search_next(&mut self, forward: bool) {
        let kw = match self.keyword.clone() {
            Some(k) => k,
            None => return,
        };
        let found = if forward {
            self.first_match_from(&kw, self.idx + 1, true)
        } else {
            self.first_match_from(&kw, self.idx, false)
        };
        if let Some(i) = found {
            self.idx = i;
            self.skip = i;
            self.y = 0;
            self.preview_scroll = 0;
            self.redraw();
        }
    }
}

// ---------------------------------------------------------------- command line
impl App {
    fn command_mode(&mut self) {
        self.out.mv(2, 2);
        self.out.clear_line();
        self.out.s(":");
        self.out.show();
        let mut text: Vec<char> = vec![];
        let mut cur = 0;
        let res = self.edit_line(":", &mut text, &mut cur, 3, None);
        match res {
            InputResult::Cancel => {
                self.out.hide();
                self.clear_status();
                self.update();
            }
            InputResult::Done(cmd) => {
                self.out.hide();
                self.exec_command(&cmd);
            }
        }
    }

    fn exec_command(&mut self, cmd: &str) {
        let words: Vec<&str> = cmd.split_whitespace().collect();
        if words.is_empty() {
            self.clear_status();
            self.update();
            return;
        }
        if words.len() == 1 {
            match words[0] {
                "q" => {
                    self.exit_app();
                    return;
                }
                "cd" => {
                    let home = home_dir();
                    self.chdir(&home, None);
                    self.push_jump(&home);
                    self.redraw();
                    return;
                }
                "e" => {
                    self.reload_keep();
                    self.redraw();
                    return;
                }
                "h" => {
                    self.help_pager();
                    return;
                }
                "reg" => {
                    self.session.preview = true;
                    self.show_reg = true;
                    self.after_layout_change();
                    self.redraw();
                    self.clear_status();
                    self.out.hide();
                    self.update();
                    return;
                }
                "config" => {
                    match self.config.path.clone() {
                        Some(p) => {
                            let dir = p.parent().map(|d| d.to_path_buf()).unwrap_or_default();
                            self.chdir(&dir, None);
                            self.push_jump(&dir);
                            let name = p
                                .file_name()
                                .map(|n| n.to_string_lossy().into_owned())
                                .unwrap_or_default();
                            if let Some(i) = self.list.iter().position(|it| it.name == name) {
                                self.put_cursor_at(i);
                            }
                            self.redraw();
                        }
                        None => {
                            self.print_error("Cannot find the config path.");
                        }
                    }
                    return;
                }
                "trash" => {
                    let t = self.paths.trash_dir.clone();
                    self.chdir(&t, None);
                    self.push_jump(&t);
                    self.redraw();
                    return;
                }
                "empty" => {
                    self.empty_trash();
                    return;
                }
                _ => {}
            }
        }
        if words.len() == 2 && words[0] == "cd" {
            let target = self.cwd.join(words[1]);
            if !target.exists() {
                self.print_error("Path does not exist.");
                return;
            }
            if let Err(e) = std::fs::read_dir(&target) {
                self.print_error(&e.to_string());
                return;
            }
            let target = std::fs::canonicalize(&target).unwrap_or(target);
            self.chdir(&target, None);
            self.push_jump(&target);
            self.redraw();
            return;
        }
        // shell command
        let shell = std::env::var("SHELL").unwrap_or_else(|_| "bash".to_string());
        let line = words.join(" ");
        self.out.hide();
        self.out.s("\x1b[?1049h");
        self.out.flush();
        let _ = std::process::Command::new(shell)
            .arg("-c")
            .arg(&line)
            .current_dir(&self.cwd)
            .status();
        self.out.s("\x1b[?1049h");
        self.out.hide();
        self.reload_keep();
        self.redraw();
    }

    fn empty_trash(&mut self) {
        self.print_error("Are you sure to empty the trash directory? (if yes: y)");
        let k = self.next_key();
        if is_char(&k, 'y') {
            self.print_info("EMPTY: Processing...");
            self.clear_status();
            if let Ok(rd) = std::fs::read_dir(&self.paths.trash_dir) {
                for e in rd.flatten() {
                    let _ = ops::remove_any(&e.path());
                }
            }
            if self.in_trash() {
                self.reload_keep();
                self.list_redraw();
            }
            self.print_info("Trash dir emptied");
            self.update();
        } else {
            self.clear_status();
            self.update();
        }
    }

    fn help_pager(&mut self) {
        let mut lines: Vec<String> = vec![];
        let w = self.w.max(1);
        for l in crate::help::HELP.split('\n') {
            for seg in preview::wrap(l, w) {
                lines.push(seg);
            }
        }
        lines.push("Press <CR> to go back.".to_string());
        let mut skip = 0usize;
        self.out.clear_all();
        self.out.mv(1, 1);
        loop {
            let h = self.h;
            self.out.clear_all();
            let avail = h.saturating_sub(1);
            let rest = lines.len().saturating_sub(skip);
            if rest > avail {
                for r in 0..avail {
                    self.out.mv(1, r + 1);
                    let l = lines[skip + r].clone();
                    self.out.s(&l);
                }
                self.out.mv(1, h);
                self.out.reverse();
                self.out.s("...");
                self.out.reset();
            } else {
                for r in 0..rest {
                    self.out.mv(1, r + 1);
                    let l = lines[skip + r].clone();
                    self.out.s(&l);
                }
            }
            let k = self.next_key();
            match k.code {
                KeyCode::Char('j') | KeyCode::Down
                    if !k.modifiers.intersects(KeyModifiers::CONTROL | KeyModifiers::ALT) =>
                {
                    skip += 1;
                }
                KeyCode::Char('k') | KeyCode::Up
                    if !k.modifiers.intersects(KeyModifiers::CONTROL | KeyModifiers::ALT) =>
                {
                    skip = skip.saturating_sub(1);
                }
                _ => break,
            }
        }
        self.redraw();
    }
}
