            if k.code == KeyCode::Esc {
                self.out.mv(2, 2);
                self.out.clear_line();
                self.out.hide();
                self.update();
                return false;
            }
            let c = match plain_char(&k) {
                Some(c) => c,
                None => continue,
            };
            buf.push(c);
            if buf.len() == 2 {
                let r = buf[0];
                if !r.is_ascii_alphanumeric() {
                    self.out.hide();
                    self.print_error("Input not supported.");
                    return false;
                }
                let op = buf[1];
                if op == 'y' || op == 'd' {
                    self.out.mv(2, 2);
                    self.out.clear_line();
                    self.out.hide();
                    if r.is_ascii_digit() {
                        return false;
                    }
                    let target = RegTarget::Named(r.to_ascii_lowercase(), r.is_ascii_uppercase());
                    let sel = self.selected_indices();
                    if op == 'y' {
                        self.yank(sel, target, true);
                    } else {
                        self.clear_selection();
                        self.delete(sel, target, true);
                    }
                    return true;
                }
                self.out.mv(2, 2);
                self.out.clear_line();
                self.out.hide();
                self.update();
                return false;
            }
            self.out.clear_line();
            self.out.mv(2, 2);
            let s: String = std::iter::once('"').chain(buf.iter().cloned()).collect();
            self.out.s(&s);
            self.out.mv(2 + 1 + buf.len(), 2);
        }
    }

    fn bulk_rename(&mut self, sel: Vec<usize>) {
        let items: Vec<Item> = sel.iter().filter_map(|i| self.list.get(*i).cloned()).collect();
        if items.is_empty() {
            self.redraw();
            return;
        }
        let editor = match self.editor_cmd() {
            Some(e) => e,
            None => {
                self.redraw();
                self.print_error("$EDITOR may not be set, or config file may be invalid.");
                return;
            }
        };
        let tmp = std::env::temp_dir().join(format!(".tmp{}", rand_suffix()));
        let content: String = items.iter().map(|i| format!("{}\n", i.name)).collect();
        if let Err(e) = std::fs::write(&tmp, content) {
            self.redraw();
            self.print_error(&e.to_string());
            return;
        }
        self.out.s("\x1b[?1049h");
        self.out.flush();
        let st = std::process::Command::new(&editor).arg(&tmp).status();
        self.out.s("\x1b[?1049h");
        self.out.hide();
        if st.is_err() {
            let _ = std::fs::remove_file(&tmp);
            self.redraw();
            self.print_error("$EDITOR may not be set, or config file may be invalid.");
            return;
        }
        let new = std::fs::read_to_string(&tmp).unwrap_or_default();
        let _ = std::fs::remove_file(&tmp);
        let names: Vec<&str> = new.lines().collect();
        if names.len() != items.len() {
            self.reload_keep();
            self.redraw();
            self.print_error("Rename failed: inconsistent number of names.");
            return;
        }
        let mut pairs = vec![];
        for (it, nn) in items.iter().zip(names.iter()) {
            if *nn == it.name {
                continue;
            }
            let to = self.cwd.join(nn);
            if std::fs::rename(&it.path, &to).is_ok() {
                pairs.push((it.path.clone(), to));
            }
        }
        let n = pairs.len();
        if n > 0 {
            self.undo.push(Op::Rename { pairs });
            self.redo.clear();
        }
        self.reload_keep();
        self.redraw();
        self.print_info(&format!("{} items renamed.", n));
    }
}

pub fn rand_suffix() -> String {
    let chars: Vec<char> = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        .chars()
        .collect();
    let mut seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(1)
        ^ (std::process::id() as u64) << 32;
    let mut s = String::new();
    for _ in 0..6 {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        s.push(chars[(seed % chars.len() as u64) as usize]);
    }
    s
}
