impl App {
    fn undo_op(&mut self, op: &Op) -> Result<Op, String> {
        match op {
            Op::Put { created, sources, dir } => {
                for p in created {
                    let _ = ops::remove_any(p);
                }
                Ok(Op::Put {
                    created: created.clone(),
                    sources: sources.clone(),
                    dir: dir.clone(),
                })
            }
            Op::Delete { moved } => {
                for (orig, trash) in moved {
                    ops::move_any(trash, orig).map_err(|e| e.to_string())?;
                }
                Ok(op.clone())
            }
            Op::Rename { pairs } => {
                for (from, to) in pairs.iter().rev() {
                    std::fs::rename(to, from).map_err(|e| e.to_string())?;
                }
                Ok(op.clone())
            }
        }
    }

    fn redo_op(&mut self, op: &Op) -> Result<Op, String> {
        match op {
            Op::Put { sources, dir, .. } => {
                let mut created = vec![];
                for it in sources {
                    let dest = ops::unique_put_path(dir, &it.name, it.is_dir);
                    ops::copy_recursive(&it.path, &dest).map_err(|e| e.to_string())?;
                    created.push(dest);
                }
                Ok(Op::Put {
                    created,
                    sources: sources.clone(),
                    dir: dir.clone(),
                })
            }
            Op::Delete { moved } => {
                let mut new = vec![];
                for (orig, _) in moved {
                    let tp = ops::to_trash(orig, &self.paths.trash_dir).map_err(|e| e.to_string())?;
                    new.push((orig.clone(), tp));
                }
                Ok(Op::Delete { moved: new })
            }
            Op::Rename { pairs } => {
                for (from, to) in pairs.iter() {
                    std::fs::rename(from, to).map_err(|e| e.to_string())?;
                }
                Ok(op.clone())
            }
        }
    }

    fn op_name(op: &Op) -> &'static str {
        match op {
            Op::Put { .. } => "PUT",
            Op::Delete { .. } => "DELETE",
            Op::Rename { .. } => "RENAME",
        }
    }

    pub fn do_undo(&mut self) {
        let op = match self.undo.pop() {
            Some(o) => o,
            None => {
                self.print_info("No operations left.");
                return;
            }
        };
        match self.undo_op(&op) {
            Ok(done) => {
                if self.log {
                    logger::info(&format!("UNDONE: {}", Self::op_name(&op)));
                }
                self.redo.push(done);
                self.reload_keep();
                self.list_redraw();
                let (sy, msg) = (self.y, format!("UNDONE: {}", Self::op_name(&op)));
                self.y = 0;
                self.print_info_nolog(&msg);
                self.y = sy;
                self.update();
            }
            Err(e) => {
                self.reload_keep();
                self.redraw();
                self.print_error(&e);
            }
        }
    }

    pub fn do_redo(&mut self) {
        let op = match self.redo.pop() {
            Some(o) => o,
            None => {
                self.print_info("No operations left.");
                return;
            }
        };
        if !matches!(op, Op::Rename { .. }) {
            self.print_process("1/1");
        }
        match self.redo_op(&op) {
            Ok(done) => {
                let msg = match op {
                    Op::Put { .. } => "REDONE: PUT",
                    Op::Delete { .. } => "REDONE DELETE",
                    Op::Rename { .. } => "REDONE: RENAME",
                };
                self.undo.push(done);
                self.reload_keep();
                self.list_redraw();
                let sy = self.y;
                self.y = 0;
                self.print_info(msg);
                self.y = sy;
                self.update();
            }
            Err(e) => {
                self.reload_keep();
                self.redraw();
                self.print_error(&e);
            }
        }
    }

    pub fn print_info_nolog(&mut self, msg: &str) {
        let l = self.log;
        self.log = false;
        self.print_info(msg);
        self.log = l;
    }

    fn unpack_item(&mut self) {
        let it = match self.cur() {
            Some(i) => i.clone(),
            None => return,
        };
        crate::unpack::unpack_cmd(self, &it);
    }
}
