// XZ / LZMA2 decoder.

pub fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        table[i as usize] = c;
    }
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc = table[((crc ^ b as u32) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFFFFFF
}

struct RangeDecoder<'a> {
    data: &'a [u8],
    pos: usize,
    range: u32,
    code: u32,
}

impl<'a> RangeDecoder<'a> {
    fn new(data: &'a [u8], pos: usize) -> Result<Self, String> {
        if pos + 5 > data.len() {
            return Err("unexpected end of input".into());
        }
        let mut code = 0u32;
        for i in 1..5 {
            code = (code << 8) | data[pos + i] as u32;
        }
        Ok(RangeDecoder { data, pos: pos + 5, range: 0xFFFFFFFF, code })
    }
    #[inline]
    fn next_byte(&mut self) -> u8 {
        let b = if self.pos < self.data.len() { self.data[self.pos] } else { 0 };
        self.pos += 1;
        b
    }
    #[inline]
    fn normalize(&mut self) {
        if self.range < (1 << 24) {
            self.range <<= 8;
            self.code = (self.code << 8) | self.next_byte() as u32;
        }
    }
    #[inline]
    fn bit(&mut self, p: &mut u16) -> u32 {
        let bound = (self.range >> 11) * (*p as u32);
        let r;
        if self.code < bound {
            self.range = bound;
            *p += (2048 - *p) >> 5;
            r = 0;
        } else {
            self.range -= bound;
            self.code -= bound;
            *p -= *p >> 5;
            r = 1;
        }
        self.normalize();
        r
    }
    fn direct(&mut self, n: u32) -> u32 {
        let mut res = 0u32;
        for _ in 0..n {
            self.range >>= 1;
            let t = if self.code >= self.range {
                self.code -= self.range;
                1
            } else {
                0
            };
            res = (res << 1) | t;
            self.normalize();
        }
        res
    }
    fn bittree(&mut self, probs: &mut [u16], n: u32) -> u32 {
        let mut m = 1usize;
        for _ in 0..n {
            m = (m << 1) | self.bit(&mut probs[m]) as usize;
        }
        (m - (1 << n)) as u32
    }
    fn rev_bittree(&mut self, probs: &mut [u16], n: u32) -> u32 {
        let mut m = 1usize;
        let mut sym = 0u32;
        for i in 0..n {
            let b = self.bit(&mut probs[m]);
            m = (m << 1) | b as usize;
            sym |= b << i;
        }
        sym
    }
}

struct LenDecoder {
    choice: u16,
    choice2: u16,
    low: Vec<[u16; 8]>,
    mid: Vec<[u16; 8]>,
    high: [u16; 256],
}

impl LenDecoder {
    fn new() -> Self {
        LenDecoder {
            choice: 1024,
            choice2: 1024,
            low: vec![[1024; 8]; 16],
            mid: vec![[1024; 8]; 16],
            high: [1024; 256],
        }
    }
    fn decode(&mut self, rc: &mut RangeDecoder, ps: usize) -> u32 {
        if rc.bit(&mut self.choice) == 0 {
            return rc.bittree(&mut self.low[ps], 3);
        }
        if rc.bit(&mut self.choice2) == 0 {
            return 8 + rc.bittree(&mut self.mid[ps], 3);
        }
        16 + rc.bittree(&mut self.high, 8)
    }
}

struct Lzma {
    lc: u32,
    lp: u32,
    pb: u32,
    literal: Vec<u16>,
    is_match: [u16; 192],
    is_rep: [u16; 12],
    is_rep_g0: [u16; 12],
    is_rep_g1: [u16; 12],
    is_rep_g2: [u16; 12],
    is_rep0_long: [u16; 192],
    pos_slot: [[u16; 64]; 4],
    pos_special: [u16; 115],
    align: [u16; 16],
    len_dec: LenDecoder,
    rep_len_dec: LenDecoder,
    state: usize,
    reps: [u32; 4],
}

impl Lzma {
    fn new(lc: u32, lp: u32, pb: u32) -> Self {
