fn lzma2_decode(data: &[u8], out: &mut Vec<u8>) -> Result<usize, String> {
    let mut pos = 0usize;
    let mut lz: Option<Lzma> = None;
    let mut dict_start = out.len();
    loop {
        if pos >= data.len() {
            return Err("unexpected end of input".into());
        }
        let ctrl = data[pos];
        pos += 1;
        if ctrl == 0 {
            return Ok(pos);
        }
        if ctrl == 1 || ctrl == 2 {
            if pos + 2 > data.len() {
                return Err("unexpected end of input".into());
            }
            let size = ((data[pos] as usize) << 8 | data[pos + 1] as usize) + 1;
            pos += 2;
            if ctrl == 1 {
                dict_start = out.len();
            }
            if pos + size > data.len() {
                return Err("unexpected end of input".into());
            }
            out.extend_from_slice(&data[pos..pos + size]);
            pos += size;
            continue;
        }
        if ctrl < 0x80 {
            return Err(format!("invalid LZMA2 control byte {}", ctrl));
        }
        if pos + 4 > data.len() {
            return Err("unexpected end of input".into());
        }
        let usize_ = (((ctrl & 0x1F) as usize) << 16 | (data[pos] as usize) << 8 | data[pos + 1] as usize) + 1;
        let psize = ((data[pos + 2] as usize) << 8 | data[pos + 3] as usize) + 1;
        pos += 4;
        let reset = (ctrl >> 5) & 3;
        if reset == 3 {
            dict_start = out.len();
        }
        if reset >= 2 {
            if pos >= data.len() {
                return Err("unexpected end of input".into());
            }
            let mut p = data[pos] as u32;
            pos += 1;
            let lc = p % 9;
            p /= 9;
            let lp = p % 5;
            let pb = p / 5;
            lz = Some(Lzma::new(lc, lp, pb));
        } else if reset == 1 {
            if let Some(l) = lz.as_mut() {
                l.reset_state();
            }
        }
        let l = lz.as_mut().ok_or("LZMA2 missing properties")?;
        if pos + psize > data.len() {
            return Err("unexpected end of input".into());
        }
        let chunk = &data[pos..pos + psize];
        let mut rc = RangeDecoder::new(chunk, 0)?;
        let end = out.len() + usize_;
        l.decode(&mut rc, out, dict_start, end)?;
        pos += psize;
    }
}

fn read_varint(d: &[u8], pos: &mut usize) -> Result<u64, String> {
    let mut v = 0u64;
    let mut shift = 0;
    loop {
        if *pos >= d.len() {
            return Err("unexpected end of input".into());
        }
        let b = d[*pos];
        *pos += 1;
        v |= ((b & 0x7F) as u64) << shift;
        if b & 0x80 == 0 {
            break;
        }
        shift += 7;
        if shift > 63 {
            return Err("invalid varint".into());
        }
    }
    Ok(v)
}

/// Decode an xz stream; errors are formatted like `XzError("...")`.
pub fn decode_xz(data: &[u8]) -> Result<Vec<u8>, String> {
    let mut out = vec![];
    let mut pos = 0usize;
    loop {
        if data.len() < pos + 12 {
            return Err("XzError(\"Invalid header magic\")".into());
        }
        if &data[pos..pos + 6] != b"\xfd7zXZ\x00" {
            return Err("XzError(\"Invalid header magic\")".into());
        }
        let flags = &data[pos + 6..pos + 8];
        let stored = u32::from_le_bytes([data[pos + 8], data[pos + 9], data[pos + 10], data[pos + 11]]);
        let calc = crc32(flags);
        if stored != calc {
            return Err(format!(
                "XzError(\"Invalid header CRC32: expected {:#010x} but got {:#010x}\")",
                stored, calc
            ));
        }
        let check = flags[1] & 0x0F;
        let check_size = match check {
            0 => 0,
            1 => 4,
            4 => 8,
            10 => 32,
            n => {
                if n == 0 {
                    0
                } else {
                    4 << ((n - 1) / 3)
                }
            }
        };
        pos += 12;
        // blocks
        loop {
            if pos >= data.len() {
                return Err("XzError(\"unexpected end of input\")".into());
            }
            let hs = data[pos];
            if hs == 0 {
                break; // index
            }
            let hsize = (hs as usize + 1) * 4;
            if pos + hsize > data.len() {
                return Err("XzError(\"unexpected end of input\")".into());
            }
            let hdr = &data[pos..pos + hsize];
            let bflags = hdr[1];
            let nfilters = (bflags & 3) as usize + 1;
            let mut p = 2usize;
            if bflags & 0x40 != 0 {
                read_varint(hdr, &mut p)?;
            }
            if bflags & 0x80 != 0 {
                read_varint(hdr, &mut p)?;
            }
            let mut lzma2_ok = false;
            for _ in 0..nfilters {
                let id = read_varint(hdr, &mut p)?;
                let psz = read_varint(hdr, &mut p)? as usize;
                p += psz;
                if id == 0x21 {
                    lzma2_ok = true;
                } else {
                    return Err("XzError(\"Unsupported filter\")".into());
                }
            }
            if !lzma2_ok {
                return Err("XzError(\"Unsupported filter\")".into());
            }
            pos += hsize;
            let start = pos;
            let used = lzma2_decode(&data[pos..], &mut out).map_err(|e| format!("XzError(\"{}\")", e))?;
            pos += used;
            // padding
            while (pos - start) % 4 != 0 {
                pos += 1;
            }
            pos += check_size;
        }
        // skip index: parse record count
        pos += 1;
        let n = read_varint(data, &mut pos)?;
        for _ in 0..n {
            read_varint(data, &mut pos)?;
            read_varint(data, &mut pos)?;
        }
        while pos % 4 != 0 {
            pos += 1;
        }
        pos += 4; // index crc
        pos += 12; // footer
        // stream padding
        while pos < data.len() && data[pos] == 0 {
            pos += 1;
        }
        if pos >= data.len() {
            break;
        }
    }
    Ok(out)
}
