    fn decode(
        &mut self,
        rc: &mut RangeDecoder,
        out: &mut Vec<u8>,
        dict_start: usize,
        end: usize,
    ) -> Result<(), String> {
        let pb_mask = (1u32 << self.pb) - 1;
