// Zstandard decoder (RFC 8878), single-threaded, in-memory.

struct FwdBits<'a> {
    d: &'a [u8],
    bitpos: usize,
}

impl<'a> FwdBits<'a> {
    fn peek(&self, n: u32) -> u32 {
        let mut v = 0u32;
        for i in 0..n as usize {
            let bp = self.bitpos + i;
            let byte = if bp / 8 < self.d.len() { self.d[bp / 8] } else { 0 };
            v |= (((byte >> (bp % 8)) & 1) as u32) << i;
        }
        v
    }
    fn read(&mut self, n: u32) -> u32 {
        let v = self.peek(n);
        self.bitpos += n as usize;
        v
    }
}

/// Backward bit reader.
struct BackBits<'a> {
    d: &'a [u8],
    /// number of bits remaining (can go negative -> overflow)
    remain: isize,
}

impl<'a> BackBits<'a> {
    fn new(d: &'a [u8]) -> Result<Self, String> {
        if d.is_empty() {
            return Err("Corrupted block detected".into());
        }
        let last = d[d.len() - 1];
        if last == 0 {
            return Err("Corrupted block detected".into());
        }
        let hb = 7 - last.leading_zeros() as isize; // index of highest bit
        let remain = (d.len() as isize - 1) * 8 + hb;
        Ok(BackBits { d, remain })
    }
    fn read(&mut self, n: u32) -> u64 {
        let mut v = 0u64;
        for _ in 0..n {
            self.remain -= 1;
            let bit = if self.remain >= 0 {
                let bp = self.remain as usize;
                ((self.d[bp / 8] >> (bp % 8)) & 1) as u64
            } else {
                0
            };
            v = (v << 1) | bit;
        }
        v
    }
}

#[derive(Clone)]
struct FseEntry {
    sym: u16,
    nbits: u8,
    base: u16,
}

#[derive(Clone)]
struct Fse {
    al: u32,
    t: Vec<FseEntry>,
}

fn build_fse(probs: &[i32], al: u32) -> Result<Fse, String> {
    let size = 1usize << al;
    let mut t = vec![FseEntry { sym: 0, nbits: 0, base: 0 }; size];
    let mut high = size as isize - 1;
    let mut next = vec![0u32; probs.len()];
    for (s, &p) in probs.iter().enumerate() {
        if p == -1 {
            t[high as usize].sym = s as u16;
            high -= 1;
            next[s] = 1;
        } else {
            next[s] = p.max(0) as u32;
        }
    }
    let step = (size >> 1) + (size >> 3) + 3;
    let mask = size - 1;
    let mut pos = 0usize;
    for (s, &p) in probs.iter().enumerate() {
        if p <= 0 {
            continue;
        }
        for _ in 0..p {
            t[pos].sym = s as u16;
            pos = (pos + step) & mask;
            while pos as isize > high {
                pos = (pos + step) & mask;
            }
        }
    }
    if pos != 0 {
        return Err("Corrupted block detected".into());
    }
    for u in 0..size {
        let s = t[u].sym as usize;
        let n = next[s];
        next[s] += 1;
        let hb = 31 - n.leading_zeros();
        let nb = al - hb;
        t[u].nbits = nb as u8;
        t[u].base = ((n << nb) as usize - size) as u16;
    }
    Ok(Fse { al, t })
}

fn read_fse_table(d: &[u8], max_sym: usize, max_al: u32) -> Result<(Fse, usize), String> {
    let mut br = FwdBits { d, bitpos: 0 };
    let al = br.read(4) + 5;
    if al > max_al {
        return Err("Corrupted block detected".into());
    }
    let mut remaining: i32 = (1 << al) + 1;
    let mut threshold: i32 = 1 << al;
    let mut nb = al + 1;
    let mut probs: Vec<i32> = vec![];
    while remaining > 1 && probs.len() <= max_sym {
        let max = (2 * threshold - 1) - remaining;
        let low = br.peek(nb - 1) as i32;
        let value;
        if low < max {
            value = low;
            br.bitpos += (nb - 1) as usize;
        } else {
            let mut v = br.peek(nb) as i32;
            if v >= threshold {
                v -= max;
            }
            value = v;
            br.bitpos += nb as usize;
        }
        let count = value - 1;
        remaining -= count.abs();
        probs.push(count);
        if count == 0 {
            loop {
                let r = br.read(2);
                for _ in 0..r {
                    probs.push(0);
                }
                if r != 3 {
                    break;
                }
            }
        }
        while remaining < threshold && nb > 1 {
            nb -= 1;
            threshold >>= 1;
        }
    }
    if remaining != 1 || probs.len() > max_sym + 1 {
        return Err("Corrupted block detected".into());
    }
    let used = (br.bitpos + 7) / 8;
    Ok((build_fse(&probs, al)?, used))
}

