struct Huff {
    max_bits: u32,
    // table indexed by max_bits bits: (symbol, nbits)
    t: Vec<(u8, u8)>,
}

fn build_huff(weights: &[u8]) -> Result<Huff, String> {
    // weights for symbols 0..n-1, last weight implied
    let mut sum: u32 = 0;
    for &w in weights {
        if w > 0 {
            sum += 1 << (w - 1);
        }
    }
    if sum == 0 {
        return Err("Corrupted block detected".into());
    }
    let max_bits = 32 - sum.leading_zeros(); // highest bit + 1
    let total = 1u32 << max_bits;
    let rest = total - sum;
    if rest == 0 || rest & (rest - 1) != 0 {
        return Err("Corrupted block detected".into());
    }
    let last_w = (31 - rest.leading_zeros()) + 1;
    let mut w: Vec<u8> = weights.to_vec();
    w.push(last_w as u8);
    let size = 1usize << max_bits;
    let mut t = vec![(0u8, 0u8); size];
    // assign codes: symbols sorted by weight ascending (longer codes first)
    let mut pos = 0usize;
    for weight in 1..=max_bits as u8 {
        for (s, &ww) in w.iter().enumerate() {
            if ww == weight {
                let nbits = max_bits + 1 - weight as u32;
                let n = 1usize << (max_bits - nbits);
                for k in 0..n {
                    if pos + k < size {
                        t[pos + k] = (s as u8, nbits as u8);
                    }
                }
                pos += n;
            }
        }
    }
    Ok(Huff { max_bits, t })
}

fn read_huff_tree(d: &[u8]) -> Result<(Huff, usize), String> {
