struct Huff {
    max_bits: u32,
    // table indexed by max_bits bits: (symbol, nbits)
    t: Vec<(u8, u8)>,
}

fn build_huff(weights: &[u8]) -> Result<Huff, String> {
    // weights for symbols 0..n-1, last weight implied
    let mut sum: u32 = 0;
    for &w in weights {
        if w > 0 {
            sum += 1 << (w - 1);
        }
    }
    if sum == 0 {
        return Err("Corrupted block detected".into());
    }
    let max_bits = 32 - sum.leading_zeros(); // highest bit + 1
    let total = 1u32 << max_bits;
    let rest = total - sum;
    if rest == 0 || rest & (rest - 1) != 0 {
        return Err("Corrupted block detected".into());
    }
    let last_w = (31 - rest.leading_zeros()) + 1;
    let mut w: Vec<u8> = weights.to_vec();
    w.push(last_w as u8);
