            let e = &ml.t[sml];
            sml = e.base as usize + br.read(e.nbits as u32) as usize;
            let e = &of.t[sof];
            sof = e.base as usize + br.read(e.nbits as u32) as usize;
        }
    }
    out.extend_from_slice(&lits[lit_pos..]);
    Ok(())
}

pub fn decode_zstd(data: &[u8]) -> Result<Vec<u8>, String> {
    let mut out = vec![];
    let mut pos = 0usize;
    while pos + 4 <= data.len() {
        let magic = u32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]);
