// Minimal tar extractor.
use std::path::{Component, Path, PathBuf};

fn octal(b: &[u8]) -> u64 {
    // GNU base-256 for large values
    if !b.is_empty() && b[0] & 0x80 != 0 {
        let mut v: u64 = (b[0] & 0x7F) as u64;
        for &x in &b[1..] {
            v = (v << 8) | x as u64;
        }
        return v;
    }
    let mut v = 0u64;
    for &c in b {
        if c == 0 || c == b' ' {
            if v > 0 {
                break;
            }
            continue;
        }
        if !(b'0'..=b'7').contains(&c) {
            break;
        }
        v = v * 8 + (c - b'0') as u64;
    }
    v
}

fn cstr(b: &[u8]) -> Vec<u8> {
    let end = b.iter().position(|&c| c == 0).unwrap_or(b.len());
    b[..end].to_vec()
}

pub fn is_tar(d: &[u8]) -> bool {
    if d.len() < 265 {
        return false;
    }
    let m = &d[257..265];
    m == b"ustar\x0000" || m == b"ustar  \x00"
}

fn safe_join(dest: &Path, name: &[u8]) -> Option<PathBuf> {
    use std::os::unix::ffi::OsStrExt;
    let p = Path::new(std::ffi::OsStr::from_bytes(name));
    let mut out = dest.to_path_buf();
    for c in p.components() {
        match c {
            Component::Normal(x) => out.push(x),
            Component::CurDir => {}
            _ => return None,
        }
    }
    if out == dest {
        return None;
    }
    Some(out)
}

pub fn extract_tar(d: &[u8], dest: &Path) -> Result<(), String> {
    const ERR: &str = "failed to iterate over archive";
    std::fs::create_dir_all(dest).map_err(|e| e.to_string())?;
    let mut pos = 0usize;
    let mut long_name: Option<Vec<u8>> = None;
    let mut long_link: Option<Vec<u8>> = None;
    let mut pax_path: Option<Vec<u8>> = None;
    let mut pax_link: Option<Vec<u8>> = None;
    loop {
        if pos + 512 > d.len() {
            break;
        }
        let h = &d[pos..pos + 512];
        if h.iter().all(|&b| b == 0) {
            break;
        }
        // checksum
        let stored = octal(&h[148..156]);
        let mut sum: u64 = 0;
        for (i, &b) in h.iter().enumerate() {
            sum += if (148..156).contains(&i) { 32 } else { b as u64 };
        }
        if stored != sum {
            return Err(ERR.into());
        }
        let size = octal(&h[124..136]) as usize;
        let typ = h[156];
        let data_start = pos + 512;
        let data_end = data_start + size;
        if data_end > d.len() {
            return Err(ERR.into());
        }
        let data = &d[data_start..data_end];
        pos = data_start + (size + 511) / 512 * 512;
        match typ {
            b'L' => {
                long_name = Some(cstr(data));
                continue;
            }
            b'K' => {
                long_link = Some(cstr(data));
                continue;
            }
            b'x' => {
                // pax extended header
                let mut i = 0;
                while i < data.len() {
                    let sp = match data[i..].iter().position(|&c| c == b' ') {
                        Some(s) => i + s,
                        None => break,
                    };
                    let len: usize = std::str::from_utf8(&data[i..sp]).ok().and_then(|s| s.parse().ok()).unwrap_or(0);
                    if len == 0 || i + len > data.len() {
                        break;
