                    let rec = &data[sp + 1..i + len - 1];
                    if let Some(eq) = rec.iter().position(|&c| c == b'=') {
                        let (k, v) = (&rec[..eq], &rec[eq + 1..]);
                        if k == b"path" {
                            pax_path = Some(v.to_vec());
                        } else if k == b"linkpath" {
                            pax_link = Some(v.to_vec());
                        }
