            l
        } else if let Some(l) = long_link.take() {
            l
        } else {
            cstr(&h[157..257])
        };
        while name.last() == Some(&b'/') && typ != b'5' {
            name.pop();
        }
        let target = match safe_join(dest, &name) {
            Some(t) => t,
            None => continue,
        };
