        let mtime = octal(&h[136..148]) as i64;
        use std::os::unix::fs::PermissionsExt;
        match typ {
            b'5' => {
                std::fs::create_dir_all(&target).map_err(|e| e.to_string())?;
                let _ = std::fs::set_permissions(&target, std::fs::Permissions::from_mode(mode));
            }
            b'2' => {
                if let Some(p) = target.parent() {
                    let _ = std::fs::create_dir_all(p);
                }
                use std::os::unix::ffi::OsStrExt;
                let _ = std::os::unix::fs::symlink(std::ffi::OsStr::from_bytes(&link), &target);
            }
            b'1' => {
                if let Some(p) = target.parent() {
                    let _ = std::fs::create_dir_all(p);
                }
                if let Some(src) = safe_join(dest, &link) {
                    let _ = std::fs::hard_link(src, &target);
                }
            }
            b'0' | 0 | b'7' => {
                if let Some(p) = target.parent() {
                    std::fs::create_dir_all(p).map_err(|e| e.to_string())?;
                }
                if crate::ops::exists(&target) {
                    let _ = std::fs::remove_file(&target);
                }
                std::fs::write(&target, data).map_err(|e| e.to_string())?;
                let _ = std::fs::set_permissions(&target, std::fs::Permissions::from_mode(mode));
                set_mtime(&target, mtime);
            }
            _ => {}
        }
    }
    Ok(())
}

pub fn set_mtime(p: &Path, secs: i64) {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    if let Ok(c) = CString::new(p.as_os_str().as_bytes()) {
        let times = [
            libc::timespec { tv_sec: secs as libc::time_t, tv_nsec: 0 },
            libc::timespec { tv_sec: secs as libc::time_t, tv_nsec: 0 },
        ];
        unsafe {
            libc::utimensat(libc::AT_FDCWD, c.as_ptr(), times.as_ptr(), 0);
        }
    }
}
