// Minimal zip extractor (stored / deflate / bzip2).
use std::io::Read;
use std::path::{Component, Path, PathBuf};

fn u16le(d: &[u8], p: usize) -> u16 {
    u16::from_le_bytes([d[p], d[p + 1]])
}
fn u32le(d: &[u8], p: usize) -> u32 {
    u32::from_le_bytes([d[p], d[p + 1], d[p + 2], d[p + 3]])
}

fn safe_join(dest: &Path, name: &str) -> Option<PathBuf> {
    let p = Path::new(name);
    let mut out = dest.to_path_buf();
    for c in p.components() {
        match c {
            Component::Normal(x) => out.push(x),
            Component::CurDir => {}
            _ => return None,
        }
    }
    Some(out)
}

pub fn extract_zip(d: &[u8], dest: &Path) -> Result<(), String> {
    // find EOCD
    let mut eocd = None;
    if d.len() >= 22 {
        let start = d.len().saturating_sub(22 + 65535);
        let mut i = d.len() - 22;
        loop {
            if u32le(d, i) == 0x06054b50 {
                eocd = Some(i);
                break;
            }
            if i == start {
                break;
            }
            i -= 1;
        }
    }
    let e = eocd.ok_or("invalid Zip archive: Could not find EOCD")?;
    let n = u16le(d, e + 10) as usize;
    let cd_off = u32le(d, e + 16) as usize;
    let mut p = cd_off;
    std::fs::create_dir_all(dest).map_err(|e| e.to_string())?;
    for _ in 0..n {
        if p + 46 > d.len() || u32le(d, p) != 0x02014b50 {
            return Err("invalid Zip archive: Invalid Central Directory header".into());
        }
        let made_by = u16le(d, p + 4);
        let method = u16le(d, p + 10);
        let csize = u32le(d, p + 20) as usize;
        let usize_ = u32le(d, p + 24) as usize;
        let nlen = u16le(d, p + 28) as usize;
        let elen = u16le(d, p + 30) as usize;
        let clen = u16le(d, p + 32) as usize;
        let ext_attr = u32le(d, p + 38);
        let loff = u32le(d, p + 42) as usize;
        let name = String::from_utf8_lossy(&d[p + 46..p + 46 + nlen]).into_owned();
        p += 46 + nlen + elen + clen;
        if loff + 30 > d.len() || u32le(d, loff) != 0x04034b50 {
            return Err("invalid Zip archive: Invalid local file header".into());
        }
        let lnlen = u16le(d, loff + 26) as usize;
        let lelen = u16le(d, loff + 28) as usize;
        let ds = loff + 30 + lnlen + lelen;
        if ds + csize > d.len() {
            return Err("invalid Zip archive: Invalid local file header".into());
        }
        let raw = &d[ds..ds + csize];
        let target = match safe_join(dest, &name) {
            Some(t) => t,
            None => continue,
        };
        if name.ends_with('/') {
            std::fs::create_dir_all(&target).map_err(|e| e.to_string())?;
            continue;
        }
        let data: Vec<u8> = match method {
            0 => raw.to_vec(),
            8 => {
                let mut dec = flate2::read::DeflateDecoder::new(raw);
                let mut v = Vec::with_capacity(usize_);
                dec.read_to_end(&mut v).map_err(|e| e.to_string())?;
                v
            }
            12 => super::bzip2::decode_bzip2(raw)?,
            _ => return Err("unsupported Zip archive: Compression method not supported".into()),
        };
        if let Some(par) = target.parent() {
            std::fs::create_dir_all(par).map_err(|e| e.to_string())?;
        }
        std::fs::write(&target, &data).map_err(|e| e.to_string())?;
        if made_by >> 8 == 3 {
            let mode = (ext_attr >> 16) & 0o777;
            if mode != 0 {
                use std::os::unix::fs::PermissionsExt;
                let _ = std::fs::set_permissions(&target, std::fs::Permissions::from_mode(mode));
            }
        }
    }
    Ok(())
}
