fn detect(d: &[u8]) -> Kind {
    if d.len() < 2 {
        slice_panic(2, d.len());
    }
    match (d[0], d[1]) {
        (0x1F, 0x8B) => return Kind::Gzip,
        (0x1F, 0x9D) => return Kind::Unsupported("tar(LZW)"),
        (0x1F, 0xA0) => return Kind::Unsupported("tar(LZH)"),
        (0x78, 0x01) | (0x78, 0x5E) | (0x78, 0x9C) | (0x78, 0xDA) | (0x78, 0x20) | (0x78, 0x7D)
        | (0x78, 0xBB) | (0x78, 0xF9) => return Kind::Unsupported("zlib"),
        _ => {}
    }
    if d.len() < 6 {
        slice_panic(6, d.len());
    }
    if &d[..6] == b"\xfd7zXZ\x00" {
        return Kind::Xz;
    }
    if &d[..6] == b"7z\xbc\xaf\x27\x1c" {
        return Kind::Unsupported("7z");
    }
    if d.len() < 7 {
        slice_panic(7, d.len());
    }
    if &d[..7] == b"Rar!\x1a\x07\x00" {
        return Kind::Unsupported("rar v1.50");
    }
    if d.len() < 8 {
        slice_panic(8, d.len());
    }
    if &d[..8] == b"Rar!\x1a\x07\x01\x00" {
        return Kind::Unsupported("rar v5.00");
    }
    if d.starts_with(b"BZh") {
        return Kind::Unsupported("Bzip2");
    }
    if d.starts_with(b"PK\x03\x04") {
        return Kind::Zip;
    }
    if d.starts_with(b"\x28\xb5\x2f\xfd") {
        return Kind::Zstd;
    }
    if d.starts_with(b"LZIP") {
        return Kind::Unsupported("lzip");
    }
    if tar::is_tar(d) {
        return Kind::Tar;
    }
    Kind::NotArchive
}

fn write_or_extract(data: &[u8], dest: &std::path::Path) -> Result<(), String> {
    if tar::is_tar(data) {
        tar::extract_tar(data, dest)
    } else {
        std::fs::write(dest, data).map_err(|e| e.to_string())
    }
}

pub fn unpack_cmd(app: &mut App, it: &Item) {
    app.print_info("Unpacking...");
    let start = Instant::now();
    let data = match std::fs::File::open(&it.path).and_then(|mut f| {
        let mut v = vec![];
        f.read_to_end(&mut v).map(|_| v)
    }) {
        Ok(d) => d,
        Err(e) => {
            app.print_error(&e.to_string());
            return;
        }
    };
    app.out.flush();
    let dest = crate::ops::unique_suffix_path(&app.cwd, &it.name);
    let res: Result<(), String> = match detect(&data) {
        Kind::NotArchive => {
            app.print_error("Seems not an archive file.");
            return;
        }
        Kind::Unsupported(n) => {
            app.print_error(&format!("Cannot unpack this type: {}", n));
            return;
        }
        Kind::Gzip => {
            let _ = std::fs::File::create(&dest);
            let mut dec = flate2::read::GzDecoder::new(&data[..]);
            let mut out = vec![];
            match dec.read_to_end(&mut out) {
                Ok(_) => {
                    if tar::is_tar(&out) {
                        let _ = std::fs::remove_file(&dest);
                    }
                    write_or_extract(&out, &dest)
                }
                Err(e) => Err(e.to_string()),
            }
        }
