            Ok(out) => write_or_extract(&out, &dest),
            Err(e) => fake_panic(
                "src/magic_packed.rs:232:51",
                format!("called `Result::unwrap()` on an `Err` value: {}", e),
            ),
        },
        Kind::Zstd => match zstd::decode_zstd(&data) {
            Ok(out) => write_or_extract(&out, &dest),
            Err(e) => fake_panic(
                "src/magic_packed.rs:250:58",
                format!(
                    "called `Result::unwrap()` on an `Err` value: Custom {{ kind: Other, error: \"{}\" }}",
                    e
                ),
            ),
        },
        Kind::Zip => zip::extract_zip(&data, &dest),
        Kind::Tar => tar::extract_tar(&data, &dest),
    };
    match res {
        Ok(_) => {
            app.reload_keep();
            app.redraw();
            let secs = start.elapsed().as_secs_f64();
            app.print_info(&format!("Unpacked. [{:.2}s]", secs));
        }
        Err(e) => {
            app.print_error(&e);
        }
    }
}
