new = '''pub fn file_content(path: &Path) -> Content {
    let mut f = match std::fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return Content::Plain("(file not readable)".to_string()),
    };
    let size = match f.metadata() {
        Ok(m) if m.is_file() => m.len(),
        Ok(_) => return Content::Nothing,
        Err(_) => return Content::Plain("(file not readable)".to_string()),
    };
    let mut head = vec![0u8; 1024];
    let mut n = 0;
    while n < head.len() {
        match f.read(&mut head[n..]) {
            Ok(0) => break,
            Ok(k) => n += k,
            Err(_) => return Content::Plain("(file not readable)".to_string()),
        }
    }
    head.truncate(n);
    if is_image(&head[..head.len().min(12)]) {
        return Content::Image;
    }
    if is_binary(&head) {
        return Content::Plain("(binary file)".to_string());
    }
    if size > 1_000_000 {
        return Content::Plain("(text too big for preview: over 1MB)".to_string());
    }
    let mut buf = head;
    if f.read_to_end(&mut buf).is_err() {
        return Content::Plain("(file not readable)".to_string());
    }
    match String::from_utf8(buf) {
        Ok(s) => Content::Text(text_lines(&s)),
        Err(_) => Content::Nothing,
    }
}

