                    "called `Result::unwrap()` on an `Err` value: Custom {{ kind: Other, error: \\"{}\\" }}",
                    e
                ),
            ),
        },
        Kind::Zip => zip::extract_zip(&data, &dest),
        Kind::Tar => tar::extract_tar(&data, &dest),
    }
}
